import type { CRDocument } from '../types';

export const docs: CRDocument[] = [
  {
    id: "incense-evening",
    title: { en: "Evening Raising of Incense", ar: "رفع بخور عشية" },
    blocks: [
      { kind: 'note', text: { en: "The Evening Raising of Incense (Vespers) is prayed at sunset, commemorating the evening sacrifice offered in the Temple.", ar: "صلاة رفع بخور عشية تُصلى عند الغروب" } },
      { kind: 'heading', text: { en: "The Thanksgiving Prayer", ar: "صلاة الشكر" } },
      { kind: 'prayer', text: { en: "Have mercy on us, O God, the Father, the Pantocrator. All-Holy Trinity, have mercy on us.", ar: "إرحمنا يا الله الآب ضابط الكل. أيها الثالوث القدوس إرحمنا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "O Lord, God of the powers, be with us, for we have no helper in our tribulations and afflictions but You.", ar: "أيها الرب إله القوات كن معنا، لأنه ليس لنا معين في شدائدنا وضيقاتنا سواك." } },
      { kind: 'prayer', text: { en: "Make us worthy to pray thankfully:", ar: "وإجعلنا مستحقين أن نقول بشكر:" } },
      { kind: 'prayer', text: { en: "Our Father who art in heaven, hallowed be Thy name. Thy kingdom come. Thy will be done, on earth as it is in heaven. Give us this day our daily bread; and forgive us our trespasses, as we forgive those who trespass against us; and lead us not into temptation, but deliver us from the evil one. In Christ Jesus our Lord, for Thine is the kingdom and the power and the glory forever. Amen.", ar: "أبانا الذي في السموات، ليتقدس إسمك. ليأت ملكوتك. لتكن مشيئتك، كما في السماء كذلك على الأرض. خبزنا كفافنا أعطنا اليوم. وأغفر لنا ذنوبنا، كما نغفر نحن أيضاً للمذنبين إلينا. ولا تدخلنا في تجربة، لكن نجنا من الشرير. بالمسيح يسوع ربنا، لأن لك الملك والقوة والمجد إلى الأبد. آمين." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "In Christ Jesus our Lord.", ar: "بالمسيح يسوع ربنا." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Pray.", ar: "صلوا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Stand up for prayer.", ar: "للصلاة قفوا." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'prayer', text: { en: "Peace be with all.", ar: "السلام لجميعكم." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "And with your spirit.", ar: "ولروحك أيضاً." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Let us give thanks to the beneficent and merciful God, the Father of our Lord, God, and Savior Jesus Christ.", ar: "فلنشكر صانع الخيرات، الرحوم الله أبا ربنا وإلهنا ومخلصنا يسوع المسيح." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "For He has covered us, helped us, guarded us, accepted us to Himself, spared us, supported us, and has brought us to this hour.", ar: "لأنه سترنا وأعاننا وحفظنا وقبلنا إليه وشفق علينا وعضدنا وأتى بنا إلى هذه الساعة." } },
      { kind: 'prayer', text: { en: "Let us also ask Him, the Lord our God, the Pantocrator, to guard us in all peace this holy day and all the days of our life.", ar: "هو أيضاً فلنسأله أن يحفظنا في هذا اليوم المقدس، وكل أيام حياتنا بكل سلام، ضابط الكل الرب إلهنا." } },
      { kind: 'prayer', text: { en: "Let us pray.", ar: "صلوا." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'prayer', text: { en: "Lord have mercy.", ar: "يا ربُّ إرحَم." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "O Master, Lord, God the Pantocrator, the Father of our Lord, God, and Savior Jesus Christ, we thank You for everything, concerning everything, and in everything.", ar: "أيها السيد الرب الإله ضابط الكل أبو ربنا وإلهنا ومخلصنا يسوع المسيح، نشكرك على كل حال ومن أجل كل حال وفي كل حال." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "For You have covered us, helped us, guarded us, accepted us to Yourself, spared us, supported us, and have brought us to this hour.", ar: "لأنك سترتنا وأعنتنا وحفظتنا وقبلتنا إليك وشفقت علينا وعضدتنا وأتيت بنا إلى هذه الساعة." } },
      { kind: 'prayer', text: { en: "Pray that God may have mercy and compassion on us, hear us, help us and accept the supplications and prayers of His saints, for that which is good on our behalf at all times*; and forgive us our sins.", ar: "أُطلبوا لكي يرحمنا الله، ويتراءف علينا ويسمعنا، ويعيننا، ويقبل سؤالات وطلبات قديسيه منهم بالصلاح عنا في كل حين* ويغفر لنا خطايانا." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'rubric', text: { en: "* In the presence of a bishop, the following part is added:", ar: "* في حضور الأب الأسقف، يقول الشماس هذه القطعة:" } },
      { kind: 'prayer', text: { en: "And to keep the life and standing of our honored father, Pope Abba (…) and his partner in the liturgy, our father the bishop (metropolitan), Abba (...);", ar: "وأن يحفظ حياة وقيام أبينا المكرم البابا الأنبا (...)، وشريكه في الخدمة الرسولية أبينا الأسقف (المطران) أنبا (...)." } },
      { kind: 'prayer', text: { en: "Lord have mercy.", ar: "يا ربُّ إرحَم." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Therefore, we ask and entreat Your goodness, O Lover of Mankind, grant us to complete this holy day and all the days of our life in all peace with Your fear.", ar: "من أجل هذا نسأل ونطلب من صلاحك يا محب البشر، إمنحنا أن نكمل هذا اليوم المقدس وكل أيام حياتنا بكل سلام مع مخافتك." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "All envy, all temptation, all the work of Satan, the counsel of wicked men and the rising up of enemies, hidden and manifest, take them away from us, and from all Your people,", ar: "كل حسد وكل تجربة وكل فعل الشيطان ومؤامرة الناس الأشرار وقيام الأعداء الخفيين والظاهرين. إنزعها عنا، وعن سائر شعبك،" } },
      { kind: 'prayer', text: { en: "and from this church,", ar: "وعن هذه الكنيسة،" } },
      { kind: 'prayer', text: { en: "(and from this table,)", ar: "(وعن هذه المائدة،)" } },
      { kind: 'prayer', text: { en: "and from this, Your holy place.", ar: "وعن موضعك المقدس هذا." } },
      { kind: 'prayer', text: { en: "But those things which are good and profitable do provide for us, for it is You who have given us the authority to tread on serpents and scorpions, and upon all the power of the enemy.", ar: "أما الصالحات والنافعات فارزقنا إياها، لأنك أنت الذي أعطيتنا السلطان أن ندوس على الحيات والعقارب وكل قوة العدو." } },
      { kind: 'prayer', text: { en: "And lead us not into temptation, but deliver us from the evil one, by the grace, compassion and love-of-mankind, of Your only-begotten Son, our Lord, God, and Savior, Jesus Christ.", ar: "ولا تدخلنا في تجربة، لكن نجنا من الشرير. بالنعمة والرأفات ومحبة البشر اللواتي لإبنك الوحيد، ربنا وإلهنا ومخلصنا يسوع المسيح." } },
      { kind: 'prayer', text: { en: "Through whom the glory, the honor, the dominion, and the worship are due unto You, with Him and the Holy Spirit, the Giver of Life, who is of one essence with You, now and at all times, and unto the age of all ages. Amen.", ar: "هذا الذي من قبله المجد والإكرام والعزة والسجود تليق بك معه، مع الروح القدس المحيي المساوي لك. الآن وكل أوان وإلى دهر الدهور. آمين." } },
      { kind: 'rubric', text: { en: "(The priest raises the incense while the Verses of Cymbals are chanted)", ar: "(يرفع الكاهن بخور وتُرتَّل أرباع الناقوس)" } },
      { kind: 'heading', text: { en: "Verses of Cymbals", ar: "أرباع الناقوس" } },
      { kind: 'prayer', text: { en: "Lord have mercy.", ar: "يارب إرحم." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'rubric', text: { en: "Sunday tune (Watos)", ar: "اللحن الواطس (الأحد)" } },
      { kind: 'prayer', text: { en: "We worship the Father and the Son, and the Holy Spirit, the holy and co-essential Trinity.", ar: "نسجد للاب والابن والروح القدس الثالوث القدوس المساوي في الجوهر." } },
      { kind: 'prayer', text: { en: "Hail to the Church, the house of the angels, hail to the Virgin, who gave birth to our Savior.", ar: "السلام للكنيسة بيت الملائكة السلام للعذراء التي ولدت مخلصنا." } },
      { kind: 'rubric', text: { en: "Weekday tune (Adam)", ar: "اللحن الآدام (أيام الأسبوع)" } },
      { kind: 'prayer', text: { en: "O come let us worship, the Holy Trinity, the Father and the Son, and the Holy Spirit.", ar: "تعالوا فلنسجد، للثالوث القدوس، الذي هو الأب والإبن، والروح القدس." } },
      { kind: 'prayer', text: { en: "We the Christian people, for He is our true God.", ar: "نحن الشعوب المسيحيين، لأن هذا هو إلهنا الحقيقي." } },
      { kind: 'prayer', text: { en: "We have hope, in Saint Mary, that God will have mercy upon us, through her intercessions.", ar: "لنا رجاء، في القديسة مريم، الله يرحمنا، بشفاعاتها." } },
      { kind: 'prayer', text: { en: "All calmness, in the world, is through the prayers, of Saint Mary the Virgin.", ar: "كل هدوء، في العالم، من قبل صلاة، القديسة مريم العذراء." } },
      { kind: 'prayer', text: { en: "Hail to you O Mary, the beautiful dove, who gave birth to us, God the Word.", ar: "السلام لك يا مريم الحمامة الحسنة التي ولدت لنا الله الكلمة." } },
      { kind: 'prayer', text: { en: "Hail to you O Mary, a holy hail, hail to you O Mary, the Mother of the Holy One.", ar: "السلام لك يا مريم سلام مقدس السلام لك يا مريم ام القدوس." } },
      { kind: 'prayer', text: { en: "Hail to her who found grace, the Lord is with you, hail to her who received from the angel, the joy of the world.", ar: "السلام للتى وجدت نعمة الرب معك السلام للتى قبلت من الملاك فرح العالم." } },
      { kind: 'prayer', text: { en: "Hail to Michael, the great archangel, hail to Gabriel, the Announcer.", ar: "السلام لميخائيل رئيس الملائكة العظيم. السلام لغبريال المبشر المختار." } },
      { kind: 'prayer', text: { en: "Hail to the Cherubim, hail to the Seraphim, hail to all the heavenly orders.", ar: "السلام للشاروبيم السلام للسيرافيم السلام لجميع الطغمات السمائية." } },
      { kind: 'prayer', text: { en: "Hail to John, the great forerunner, hail to the priest, the relative of Emmanuel.", ar: "السلام ليوحنا السابق العظيم السلام للكاهن نسيب عمانوئيل." } },
      { kind: 'prayer', text: { en: "Hail to my masters and fathers, the Apostles, hail to the Disciples, of our Lord Jesus Christ.", ar: "السلام لساداتي الاباء الرسل. السلام لتلاميذ ربنا يسوع المسيح." } },
      { kind: 'prayer', text: { en: "Hail to you O martyr, hail to the Evangelist, hail to the Apostle, Abba Mark the beholder of God.", ar: "السلام لك ايها الشهيد السلام للانجيلي السلام للرسول مرقس ناظر الاله." } },
      { kind: 'rubric', text: { en: "When commemorating the martyrs", ar: "عند تذكار الشهداء" } },
      { kind: 'prayer', text: { en: "Hail to you O martyrs, hail to the courageous heroes, hail to the struggle-mantled, my lord prince George, Theodore the general, Philopater Mercurius, Abba Mina of Fayat.", ar: "السلام لكم أيها الشهداء، السلام للشجعان الأبطال، السلام للمجاهدين، سيدي الملك جيؤرجيوس، تيؤدوروس الإسفهسلار، مرقوريوس محب الآب، أبا مينا البياضي." } },
      { kind: 'prayer', text: { en: "Jesus Christ the same yesterday, today, and forever, in one hypostasis, we worship and glorify Him.", ar: "يسوع المسيح هو هو، أمساً واليوم وإلى الأبد، اقنوم واحد، نسجد له ونمجده." } },
      { kind: 'prayer', text: { en: "O King of peace, grant us Your peace, establish for us Your peace, and forgive us our sins.", ar: "يا ملِكَ السلامِ، أعطِنا سلامَكَ، قرِّرْ لنا سلامَكَ، واغفِرْ لنا خطايانا." } },
      { kind: 'prayer', text: { en: "Disperse the enemies, of the Church, and fortify her, that she may not be shaken forever.", ar: "فرِّقْ أعداءَ الكنيسةِ، وحصِّنْها، فلا تتزعزعُ، إلى الأبدِ." } },
      { kind: 'prayer', text: { en: "Emmanuel our God, is now in our midst, with the glory of His Father, and the Holy Spirit.", ar: "عِمَّانوئيلُ إلهُنا، في وسَطِنا الآنَ، بمجدِ أبيهِ، والروحِ القُدُسِ." } },
      { kind: 'prayer', text: { en: "May He bless us all, purify our hearts, and heal the sicknesses, of our souls and bodies.", ar: "ليباركَنا كلَّنا، ويطهِّرَ قلوبَنا، ويشفيَ أمراضَ، نفوسِنا وأجسادِنا." } },
      { kind: 'heading', text: { en: "Litany for the Departed", ar: "أوشية الراقدين" } },
      { kind: 'litany', text: { en: "Pray.", ar: "صلوا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Stand up for prayer.", ar: "للصلاة قفوا." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'litany', text: { en: "Peace be with all.", ar: "السلام لجميعكم." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "And with your spirit.", ar: "ولروحك أيضاً." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'litany', text: { en: "Again, let us ask God the Pantocrator, the Father of our Lord, God, and Savior Jesus Christ.", ar: "وأيضاً فلنسأل الله الضابط الكل، أبا ربنا وإلهنا ومخلصنا يسوع المسيح." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "We ask and entreat Your goodness, O Lover of Mankind, remember, O Lord, the souls of Your servants who have fallen asleep, our fathers and our brethren.", ar: "نسأل ونطلب من صلاحك يا محب البشر، أُذكر يا رب أنفس عبيدك الذين رقدوا، آبائنا وإخوتنا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Pray for our fathers and brethren who have fallen asleep and reposed in the faith of Christ since the beginning our holy fathers, the archbishops, our fathers the bishops, our fathers the hegumens, our fathers the priests, our brethren the deacons, our fathers the monks, and our fathers the laymen, and for the full repose of the Christians,", ar: "أُطلبوا عن آبائنا وإخوتنا الذين رقدوا، وتنيحوا في الإيمان بالمسيح منذ البدء. آبائنا القديسين رؤساء الأساقفة، وآبائنا الأساقفة، وآبائنا القمامصة، وآبائنا القسوس، وإخوتنا الشمامسة، وآبائنا الرهبان، وآبائنا العلمانيين، وعن نياح كل المسيحيين." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'litany', text: { en: "that Christ our God may repose all their souls in the Paradise of joy, and we too, accord mercy unto us, and forgive us our sins.", ar: "لكي المسيح إلهنا ينيح نفوسهم أجمعين في فردوس النعيم، ونحن أيضاً يصنع معنا رحمة، ويغفر لنا خطايانا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Lord have mercy.", ar: "يا ربُّ إرحَم." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'litany', text: { en: "Graciously, O Lord, repose all their souls in the bosom of our holy fathers Abraham, Isaac and Jacob.", ar: "تفضل يا رب نيح نفوسهم جميعاً في حضن آبائنا القديسين، إبراهيم وإسحق ويعقوب." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Sustain them in a green pasture, by the water of rest in the Paradise of joy,", ar: "عُلهُم في موضع خضرة على ماء الراحة في فردوس النعيم." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "the place out of which grief, sorrow and groaning have fled away in the light of Your saints.", ar: "الموضع الذي هرب منه الحزن والكآبة والتنهدُ في نور قديسيك." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Raise up their bodies also on the Day which You have appointed, according to Your true promises, which are without lie.", ar: "أقم أجسادهم في اليوم الذي رسمته كمواعيدِكَ الحقيقية غير الكاذبة." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Grant them the good things of Your promises, that which an eye has not seen nor ear heard, neither have come upon the heart of man; the things which You, O God, have prepared for those who love Your holy name.", ar: "هب لهم خيرات مواعيدك، ما لم تره عين ولم تسمع به أذن، ولم يخطر على قلب بشر. ما أعددته يا الله لمحبي إسمك القدوس." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "For there is no death for Your servants, but a departure.", ar: "لأنه لا يكون موت لعبيدك، بل هو إنتقال." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Even if any negligence or heedlessness has overtaken them as men, since they were clothed in flesh and dwelt in this world.", ar: "وان كان لحقهم توانٍ، أو تفريط كبشر، وقد لبسوا جسداً. وسكنوا في هذا العالم." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "O God, as the Good One and Lover of Mankind, graciously accord, O Lord—Your servants, the orthodox Christians who are in the whole world, from East to west and from north to south, each one according to his name and each one according to her name, O Lord, repose and forgive them.", ar: "فأنت كصالح ومحب البشر، اللهُمَّ تفضل عبيدك المسيحيين الأرثوذكسيين الذين في المسكونة كلها، من مشارق الشمس إلى مغارِبها، ومن الشمال إلى الجنوب، كل واحدٍ بإسمِه وكل واحدةٍ بإسمها، يا ربُ نيحهم، وإغفر لهم." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "For no one is pure and without blemish even though his life on earth be a single day.", ar: "فانه ليس أحدٌ طاهراً من دنس، ولو كانت حياتُه يوماً واحداً على الأرض." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "As for those, O Lord, whose souls You have taken, repose them, and may they be worthy of the kingdom of the heavens.", ar: "أما هم يا ربُ الذين أخذت نفوسَهم، نيحهم وليستحقوا ملكوت السموات." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "As for us all, grant us our Christian perfection that would be pleasing to You,", ar: "وأما نحن كلنا فهب لنا كماَلنا المسيحي الذي يرضيك أمامك." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "and give them and us a share and an inheritance with all Your saints.", ar: "وأعطهم وإيانا نصيباً وميراثاً مع كافة قديسيك." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Lord have mercy.", ar: "يا ربُّ إرحَم." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'rubric', text: { en: "Optional", ar: "اختياري" } },
      { kind: 'heading', text: { en: "Litany for the Sick", ar: "أوشية المرضى" } },
      { kind: 'rubric', text: { en: "A Matins litany, optional for vespers.", ar: "من أواشي باكر، وتُقال اختيارياً في العشية." } },
      { kind: 'litany', text: { en: "Pray.", ar: "صلوا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Stand up for prayer.", ar: "للصلاة قفوا." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'litany', text: { en: "Peace be with all.", ar: "السلام لجميعكم." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "And with your spirit.", ar: "ولروحك أيضاً." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'litany', text: { en: "Again, let us ask God the Pantocrator, the Father of our Lord, God, and Savior Jesus Christ.", ar: "وأيضاً فلنسأل الله الضابط الكل، أبا ربنا وإلهنا ومخلصنا يسوع المسيح." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "We ask and entreat Your goodness, O Lover of Mankind, remember, O Lord, the sick among Your people.", ar: "نسأل ونطلب من صلاحك يا محب البشر، أُذكر يا رب مرضى شعبك." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Pray for our fathers and our brethren who are sick with any sickness, whether in this place or in any place, that Christ our God may grant us, with them, health and healing, and forgive us our sins.", ar: "أُطلبوا عن آبائنا وإخوتنا المرضى بكل مرضٍ، إن كان في هذا المسكن أو بكل موضع، لكي المسيح إلهنا ينعم لنا ولهم بالعافية والشفاء، ويغفر لنا خطايانا." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'litany', text: { en: "Lord have mercy.", ar: "يا ربُّ إرحَم." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'litany', text: { en: "You have visited them with mercies and compassion, heal them.", ar: "تعهّدهم بالمراحم والرأفات إشفهم." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Take away from them and from us, all sickness and all disease; the spirit of sickness chase away.", ar: "إنزع عنهم وعنا كل مرضٍ وكل سقمٍ، وروح الأمراض أطرده." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Those who have long lain in sickness, raise up and comfort.", ar: "والذين أبطأوا مطروحين في الأمراض أقمهم وعزهم." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Those who are afflicted by unclean spirits, set them all free.", ar: "والمعذبين من الأرواح النجسة، اعتقهم جميعاً." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Those who are in prisons or dungeons, those who are in exile or captivity, and those who are held in bitter bondage, O Lord, set them all free and have mercy upon them.", ar: "الذين في السجون أو المطابق، أو الذين في النفي أو السبي أو المقبوض عليهم في عبودية مرة، يا رب اعتقهم جميعهم وإرحمهم." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "For You are He who loosens the bound and uplifts the fallen; the hope of those who have no hope and the help of those who have no helper; the comfort of the fainthearted; the harbor of those in the storm.", ar: "لأنك أنت الذي تحل المربوطين وتقيم الساقطين. رجاء من ليس له رجاء، ومعين من ليس له معين. عزاء صغيري القلوب، ميناء الذين في العاصف." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "All souls that are distressed or bound, grant them mercy, O Lord; grant them rest, grant them refreshment, grant them grace, grant them help, grant them salvation, grant them the forgiveness of their sins and their iniquities.", ar: "كل الأنفس المتضايقة، والمقبوض عليها. أعطها يا رب رحمةَ، أعطها نياحاً، أعطها برودة، أعطها نعمة، أعطها معونة، أعطها خلاصاً، أعطها غفران خطاياها وآثامها." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "As for us also, O Lord, the maladies of our souls, heal; and those of our bodies too, do cure.", ar: "ونحن أيضاً يا رب، أمراض نفوسنا، إشفها والتي لأجسادنا، عافها." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "O You, the true Physician of our souls and our bodies, the Bishop of all flesh, visit us with Your salvation.", ar: "أيها الطبيب الحقيقي الذي لأنفسنا، وأجسادنا، يا مدبر كل جسدٍ تعهدنا بخلاصك." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Lord have mercy.", ar: "يا ربُّ إرحَم." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'rubric', text: { en: "Optional", ar: "اختياري" } },
      { kind: 'heading', text: { en: "Litany for the Travelers", ar: "أوشية المسافرين" } },
      { kind: 'rubric', text: { en: "A Matins litany, optional for vespers.", ar: "من أواشي باكر، وتُقال اختيارياً في العشية." } },
      { kind: 'litany', text: { en: "Pray.", ar: "صلوا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Stand up for prayer.", ar: "للصلاة قفوا." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'litany', text: { en: "Peace be with all.", ar: "السلام لجميعكم." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "And with your spirit.", ar: "ولروحك أيضاً." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'litany', text: { en: "We ask and entreat Your goodness, O Lover of Mankind, remember, O Lord, our fathers and our brethren who are traveling.", ar: "نسأل ونطلب من صلاحك يا محب البشر، أُذكر يا رب آباءنا وإخوتنا المسافرين." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Pray for our fathers and our brethren who are traveling, or those who intend to travel anywhere, that God may straighten all their ways, whether by sea, rivers, lakes, roads, air, or those who are traveling by any other means, that Christ our God may bring them back to their own homes in peace, and forgive us our sins.", ar: "أُطلبوا عن آبائنا وإخوتنا المسافرين، والذين يضمرون السفر في كل موضع، لكي يُسهل طرقهم أجمعين إن كان في البحر أو الأنهار أو البحيرات أو الطرق المسلوكة أو الجو أو المسافرين بكل نوع، لكي المسيح إلهنا يردهم إلى مساكنهم سالمين، ويغفر لنا خطايانا." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'litany', text: { en: "Lord have mercy.", ar: "يا ربُّ إرحَم." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'litany', text: { en: "And those who intend to travel anywhere, straighten all their ways, whether by sea, rivers, lakes, roads, air, or those who are traveling by any other means, everyone anywhere. Lead them into a haven of calm, a haven of safety.", ar: "والذين يضمرون السفر في كل مكان، سهل طرقهم أجمعين، إن كان في البحر أو الأنهار أو البحيرات أو الطرق المسلوكة أو الجو أو السالكين بكل نوع، كل أحد بكل موضع ردهم إلى ميناء هادئة، ميناء الخلاص." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Graciously accompany them in their departure and be their companion in their travel.", ar: "تفضل إصحبهم في الإقلاع، وإصحبهم في المسير." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Bring them back to their own, rejoicing with joy and safe in security.", ar: "ردهم إلى منازلهم بالفرح فرحين، وبالعافية معافين." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "In work, be a partner with Your servants in every good deed.", ar: "إشترك في العمل مع عبيدك في كل عمل صالح." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "As for us, O Lord, keep our sojourn in this life without harm, without storm, and undisturbed to the end.", ar: "ونحن أيضاً يا رب غربتنا في هذا العمر، إحفظها بغير مضرة ولا عاصف ولا قلق إلى الإنقضاء." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Lord have mercy.", ar: "يا ربُّ إرحَم." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'rubric', text: { en: "Optional", ar: "اختياري" } },
      { kind: 'heading', text: { en: "Litany for the Oblations", ar: "أوشية القرابين" } },
      { kind: 'rubric', text: { en: "A Matins litany, optional for vespers.", ar: "من أواشي باكر، وتُقال اختيارياً في العشية." } },
      { kind: 'litany', text: { en: "We ask and entreat Your goodness, O Lover of Mankind, remember, O Lord, the sacrifices, the offerings and the thanksgivings of those who have offered to the honor and glory to Your holy name.", ar: "نسأل ونطلب من صلاحك يا محب البشر، أُذكر يا رب صعائد وقرابين وشكر الذين يقربون كرامة ومجداً لإسمك القدوس." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Pray for those who tend to the sacrifices, offerings, first-fruits, oil, incense, coverings, reading books, and altar vessels, that Christ our God may reward them in the heavenly Jerusalem, and forgive us our sins.", ar: "أُطلبوا عن المهتمين بالصعائد، والقرابين، والبكور، والزيت، والبخور، والستور، وكتب القراءة، وأواني المذبح، لكي المسيح إلهنا يكافئهم في أورشليم السمائية، ويغفر لنا خطايانا." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'litany', text: { en: "Lord have mercy.", ar: "يا ربُّ إرحَم." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'litany', text: { en: "Receive them upon Your holy, rational altar of heaven as a sweet savor of incense before Your greatness in the heavens, through the service of Your holy angels and archangels.", ar: "إقبلها إليك على مذبحك المقدس، الناطق السمائي رائحة بخور، تدخل إلى عظمتك التي في السموات. بواسطة خدمة ملائكتك ورؤساء ملائكتك المقدسين." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "As You have received the gifts of the righteous Abel, the sacrifice of our father Abraham and the two mites of the widow,", ar: "وكما قبلت إليك قرابين هابيل الصديق، وذبيحة أبينا إبراهيم، وفلسي الأرملة." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "so also receive the thank offerings of Your servants, those in abundance or those in scarcity, hidden or manifest.", ar: "هكذا أيضاً نذور عبيدك، إقبلها إليك، أصحاب الكثير وأصحاب القليل، الخفيات والظاهرات." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Those who desire to offer to You but have none, and those who have offered these gifts to You this very day,", ar: "والذين يريدون أن يقدموا لك وليس لهم، والذين قدموا لك في هذا اليوم هذه القرابين." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "give them the incorruptible instead of the corruptible, the heavenly instead of the earthly and the eternal instead of the temporal.", ar: "أعطهم الباقيات عوضاً عن الفانيات، السمائيات عوض الأرضيات، الأبديات عوض الزمنيات." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Their houses and their stores, fill them with every good thing.", ar: "بيوتهم ومخازنهم إملأها من كل الخيرات." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Surround them, O Lord, by the power of Your holy angels and archangels. As they remembered Your holy name on earth, remember them also, O Lord, in Your kingdom, and in this age too, leave them not behind.", ar: "أحطهم يا رب بقوة ملائكتك، ورؤساء ملائكتك الأطهار. وكما ذكروا إسمك القدوس على الأرض، أذكرهم هم أيضاً يا رب في ملكوتك، وفي هذا الدهر لا تتركهم عنك." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Lord have mercy.", ar: "يا ربُّ إرحَم." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'heading', text: { en: "Graciously O Lord", ar: "تفضل يا رب" } },
      { kind: 'prayer', text: { en: "Graciously O Lord, keep us this night without sin. Blessed are You, O Lord the God of our fathers and exceedingly blessed, and Your holy name is full of glory forever. Amen.", ar: "تفضَّلْ يا ربُّ أنْ تَحْفَظَنا في هَذِهِ اللَّيْلَةِ بِغَيرِ خَطيَّةٍ. مُبارِكٌ أَنْتَ أيُّها الرَّبُّ إلهُ آبائِنا ومُتَزايدٌ بَرَكةً، وإسْمُكَ القُدُّوسُ مَمْلوءٌ مَجْداً إلَى الأبَدِ. آمين." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Let Your mercies be upon us, O Lord, even as we rely on You. For the eyes of all hope in You, for You give them their food in due season.", ar: "فَلْتكنْ رَحمَتُكَ عَليْنا كَمثْلِ إتِّكالِنا عَليْكَ، لأنَّ أعْيُنَ الكُلَّ تَترَجَّاكَ، لأنَّكَ أنْتَ الذي تُعْطيهم طَعامَهُم في حينِه." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Hear us, O God our Savior, the hope of the regions of the whole earth. And You O Lord, keep us and deliver us, from this generation and forever. Amen.", ar: "إسْمَعنا يا الله مُخلِّصَنا يا رَجاءَ أقْطارِ الأرْضِ كُلِّها. وأنْتَ يا ربُّ تَحْفظُنا وتُنَجِّينا مِنْ هَذا الجيلِ وإلَى الأبَدِ. آمين." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Blessed are You O Lord, teach me Your justice. Blessed are You O Lord, make me to understand Your rights. Blessed are You O Lord, enlighten me in Your righteousness.", ar: "مُبارَكٌ أنْتَ يا ربُّ، عَلِّمني عَدْلَك. مُبارَكٌ أنْتَ يا ربُّ، فَهِّمني حُقوقَكَ. مُبارَكٌ أنْتَ يا ربُّ، أنِرْ لي بِرَّك." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "O Lord, Your mercy is forever. Do not reject the works of Your hands. For You, O Lord, have become my refuge from generation to generation.", ar: "يا ربُّ رَحْمَتُكَ دائِمَةٌ إلَى الأبَدِ. أعْمالُ يَديْكَ يا ربُّ لا تَرفُضْها، لأنَّكَ صِرْتَ لي مَلجأً مِنْ جيلٍ إلَى جيلٍ." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'heading', text: { en: "The Trisagion", ar: "الثلاث تقديسات" } },
      { kind: 'prayer', text: { en: "Holy God, holy Mighty, holy Immortal, who was born of the Virgin, have mercy upon us.", ar: "قُدُّوسٌ الله، قُدُّوسٌ القَويُّ، قُدُّوسٌ الحَيُّ الَّذي لا يَموتُ، الَّذي وُلِدَ مِنَ العَذْراءِ، إرْحَمْنا." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Holy God, holy Mighty, holy Immortal, who was crucified for us, have mercy upon us.", ar: "قُدُّوسٌ الله، قُدُّوسٌ القَويُّ، قُدُّوسٌ الحَيُّ الَّذي لا يَموتُ، الَّذي صُلِبَ عنَّا، إرْحَمْنا." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Holy God, holy Mighty, holy Immortal, who rose from the dead and ascended into the heavens, have mercy upon us.", ar: "قُدُّوسٌ الله، قُدُّوسٌ القَويُّ، قُدُّوسٌ الحَيُّ الَّذي لا يَموتُ، الذي قامَ مِنَ الأمْواتِ وصَعِدَ إلَى السَّمواتِ، إرْحَمْنا." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Glory to the Father and to the Son and the Holy Spirit, now and forever and unto the ages of all ages. Amen.", ar: "المجْدُ للآبِ والإبنِ والرُّوحِ القُدُسِ، الآنَ وكلُّ أَوان وإلَى دَهْرِ الدُّهورِ. آمين." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "O Holy Trinity, have mercy upon us. O Holy Trinity, have mercy upon us. O Holy Trinity, have mercy upon us.", ar: "أيُّها الثَّالوثُ القُدُّوسُ إرْحَمْنا. أيُّها الثَّالوثُ القُدُّوسُ إرْحَمْنا. أيُّها الثَّالوثُ القُدُّوسُ إرْحَمْنا." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Lord, forgive our sins. Lord, forgive our iniquities. Lord, forgive our transgressions. Lord, be with the sick of Your people, heal them for the sake of Your holy name. Our fathers and brethren who have slept, repose their souls.", ar: "يا رَبُّ إغْفِرْ لَنا خَطايانا. يا رَبُّ إغْفِرْ لَنا آثامَنا. يا رَبُّ إغْفِرْ لَنا زَلاَّتَنا. يا رَبُّ إفْتَقدْ مَرْضَى شَعْبكَ، إشْفِهمْ مِنْ أجْل إسْمكَ القُدُّوسِ. آباؤُنا وإخْوَتنا الَّذينَ رَقدوا، يا رَبُّ نَيِّحْ نُفوسَهُم." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "O who are alone is sinless, help us and accept our prayers. For Yours is the glory, dominion, and triple holiness. Lord have mercy. Lord have mercy. Lord bless us. Amen.", ar: "يا مَنْ هُوَ بِلا خَطيَّة، يا ربُّ إرحَمنا. يا مَنْ بِلا خَطيَّةِ، يا رَبُّ أَعِنَّا، وإقْبَلْ طَلباتِنا إلَيْكَ. لأنَّ لَكَ المجْدَ والعِزَّةَ والتَّقْديسَ المثلَّثَ. يا ربُّ إرحَم. يا ربُّ إرحَم. يا رَبُّ بارِكْ. آمين." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'heading', text: { en: "Our Father", ar: "أبانا الذي" } },
      { kind: 'prayer', text: { en: "Our Father who art in heaven, hallowed be Thy name. Thy kingdom come. Thy will be done, on earth as it is in heaven. Give us this day our daily bread; and forgive us our trespasses, as we forgive those who trespass against us; and lead us not into temptation, but deliver us from the evil one. In Christ Jesus our Lord, for Thine is the kingdom and the power and the glory forever. Amen.", ar: "أبانا الذي في السموات، ليتقدس إسمك. ليأت ملكوتك. لتكن مشيئتك، كما في السماء كذلك على الأرض. خبزنا كفافنا أعطنا اليوم. وأغفر لنا ذنوبنا، كما نغفر نحن أيضاً للمذنبين إلينا. ولا تدخلنا في تجربة، لكن نجنا من الشرير. بالمسيح يسوع ربنا، لأن لك الملك والقوة والمجد إلى الأبد. آمين." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'heading', text: { en: "Introduction to the Creed", ar: "بدء قانون الإيمان" } },
      { kind: 'prayer', text: { en: "We exalt you, the Mother of the true Light, and we glorify you, O saint and Theotokos, for you brought forth unto us the Savior of the whole world; He came and saved our souls.", ar: "نُعظِّمُكِ يا أمَّ النُّورِ الحَقيقيِّ، ونُمجِّدكِ أيَّتُها العَذْراءُ القِدِّيسةُ، والِدةُ الإلهِ، لأنَّكِ وَلدْتِ لَنا مُخلِّصَ العالَم، أتَى وخَلَّصَ نُفوسَنا." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Glory to You, our Master, our King, Christ, the pride of the Apostles, the crown of the martyrs, the joy of the righteous, the steadfastness of the churches, and the forgiveness of sins.", ar: "المجْدُ لكَ يا سَيِّدُنا ومَلكُنا المسيحُ، فَخْرَ الرُّسُل، إكْليلَ الشُهداءِ، تَهْليلَ الصِدِّيقينَ، ثَباتَ الكَنائسِ، غُفْرانَ الخَطايا" }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "We proclaim the Holy Trinity in one Godhead. We worship Him. We glorify Him. Lord have mercy. Lord have mercy. Lord bless. Amen.", ar: "نُبشِّرُ بالثَّالوثِ القُدُّوسِ، لاهوتٌ واحِدٌ، نَسجُدُ لهُ ونُمجِّدهُ. يا ربُّ إرحَم. يا ربُّ إرحَم. يا رَبُّ بارِكْ. آمين." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'heading', text: { en: "The Orthodox Creed", ar: "قانون الإيمان الأرثوذكسي" } },
      { kind: 'prayer', text: { en: "We believe in one God, God the Father, the Pantocrator, who created heaven and earth, and all things, seen and unseen.", ar: "بالحقيقة نؤمن بإله واحد، الله الآب، ضابط الكل، خالق السماء والأرض، ما يُرى وما لا يُرى." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "We believe in one Lord Jesus Christ, the only-begotten Son of God, begotten of the Father before all ages.", ar: "نؤمن برب واحد يسوع المسيح، إبن الله الوحيد، المولود من الآب قبل كل الدهور." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Light out of Light, true God of true God; begotten not created, of one essence with the Father, by whom all things were made; who for us men and for our salvation, came down from heaven, and was incarnate of the Holy Spirit and of the Virgin Mary, and became man.", ar: "نور من نور، إله حق من إله حق. مولود غير مخلوق، مساوي للآب في الجوهر، الذي به كان كل شيء. هذا الذي من أجلنا نحن البشر، ومن أجل خلاصنا، نزل من السماء، وتجسد من الروح القدس ومن مريم العذراء، وتأنس." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "And He was crucified for us under Pontius Pilate, suffered and was buried. And on the third day He rose from the dead, according to the Scriptures.", ar: "وصلب عنا على عهد بيلاطس البنطي، وتألم وقبر. وقام من بين الأموات في اليوم الثالث كما في الكتب." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "He ascended into the heavens and sits at the right hand of His Father, and He is coming again in His glory to judge the living and the dead, whose kingdom shall have no end.", ar: "وصعد إلى السموات، وجلس عن يمين أبيه، وأيضاً يأتي في مجده ليدين الأحياء والأموات، الذي ليس لملكه إنقضاء." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Yes, we believe in the Holy Spirit, the Lord, the Life-Giver, who proceeds from the Father, who, with the Father and the Son, is worshippedand glorified, who spoke by the prophets.", ar: "نعم نؤمن بالروح القدس، الرب المحيي المنبثق من الآب. نسجد له ونمجده مع الآب والإبن، الناطق في الأنبياء." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "And in one holy, catholic and apostolic Church. We confess one baptism for the remission of sins.", ar: "وبكنيسة واحدة مقدسة جامعة رسولية. ونعترف بمعمودية واحدة لمغفرة الخطايا." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "We look for the resurrection of the dead, and the life of the age to come. Amen.", ar: "وننتظر قيامة الأموات وحياة الدهر الآتي. آمين." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'heading', text: { en: "O God, Have Mercy Upon Us", ar: "اللهُمَّ إرحمنا" } },
      { kind: 'prayer', text: { en: "O God, have mercy upon us, settle mercy upon us, have compassion upon us.", ar: "اللهُمَّ إرحمنا، قرر لنا رحمة، تراءف علينا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Amen.", ar: "آمين." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Hear us.", ar: "وإسمعنا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Amen.", ar: "آمين." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Bless us, keep us, and help us.", ar: "وباركنا وإحفظنا وأعنا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Amen.", ar: "آمين." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Take away Your anger from us, visit us with Your salvation, and forgive us our sins.", ar: "وإرفع غضبك عنا، وإفتقدنا بخلاصك، وإغفر لنا خطايانا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Amen.", ar: "آمين." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Lord have mercy (3).", ar: "يا ربُّ إرحَم (3)." } },
      { kind: 'heading', text: { en: "Litany for the Gospel", ar: "أوشية الإنجيل" } },
      { kind: 'litany', text: { en: "Pray.", ar: "صلوا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Stand up for prayer.", ar: "للصلاة قفوا." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'litany', text: { en: "Peace be with all.", ar: "السلام لجميعكم." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "And with your spirit.", ar: "ولروحك أيضاً." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'litany', text: { en: "O Master, Lord Jesus Christ our God, who said to His saintly, honored Disciples and holy Apostles,", ar: "أيها السيد الرب يسوع المسيح إلهنا، الذي قال لتلاميذه القديسين ورسله الأطهار المكرمين:" }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "“Many prophets and righteous men have desired to see the things which you see, and have not seen them, and to hear the things which you hear and have not heard them. But as for you, blessed are your eyes, for they see, and your ears for they hear.”", ar: "\"إن أنبياء وأبراراً كثيرين إشتهوا أن يروا ما أنتم ترون ولم يروا، وأن يسمعوا ما أنتم تسمعون ولم يسمعوا. أما أنتم فطوبى لأعينكم لأنها تبصر، ولآذانكم لأنها تسمع.\"" } },
      { kind: 'litany', text: { en: "May we be worthy to hear and to act according to Your Holy Gospels, through the prayers of Your saints.", ar: "فلنستحق أن نسمع ونعمل بأناجيلك المقدسة بطلبات قديسيك." } },
      { kind: 'litany', text: { en: "Pray for the Holy Gospel.", ar: "صلوا من أجل الإنجيل المقدس." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'litany', text: { en: "Lord have mercy.", ar: "يا ربُّ إرحَم." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'litany', text: { en: "Remember also, O our Master, all those who have bidden us to remember them in our supplications and prayers which we offer up unto You, O Lord our God. Those who already fallen asleep, repose them.", ar: "أُذكر أيضاً يا سيدنا كل الذين أوصونا أن نذكرهم في تضرعاتنا وطلباتنا التي نصعدها إليك أيها الرب إلهنا. الذين سبقوا فرقدوا، نيحهم. المرضى إشفهم." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Those who are sick, heal them. For You are the life of us all, the salvation of us all, the hope of us all, the healing of us all, and the resurrection of us all.", ar: "لأنك أنت حياتنا كلنا، وخلاصنا كلنا، ورجاؤنا كلنا، وشفاؤنا كلنا، وقيامتنا كلنا." } },
      { kind: 'heading', text: { en: "Another Litany for the Gospel", ar: "أوشية إنجيل أخرى" } },
      { kind: 'litany', text: { en: "O Master, Lord Jesus Christ our God, who sent His saintly, honored Disciples and holy Apostles into all the world", ar: "أيها السيد الرب يسوع المسيح إلهنا الذي أرسل تلاميذه القديسين المكرمين، ورسله الأطهار في العالم كله." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "that they may preach the Gospel of Your kingdom and teach all nations Your true knowledge.", ar: "ليكرزوا بإنجيل ملكوتك ويعلموا كل الأمم معرفتك الحقيقية." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "We ask You, O our Master, open the ears of our hearts that we may hear Your Holy Gospel—", ar: "نسألك يا سيدنا، إفتح أذان قلوبنا لكي نسمع أناجيلك المقدسة." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Pray for the Holy Gospel.", ar: "صلوا من أجل الإنجيل المقدس." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'litany', text: { en: "Lord have mercy.", ar: "يا ربُّ إرحَم." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'litany', text: { en: "And open the senses of our souls, and may we be worthy not only to be hearers but to act according to Your holy commandments though the good will of God, Your good Father.", ar: "وإفتح حواس نفوسنا، ولنستحق أن نكون ليس فقط سامعين، بل عاملين أيضاً بأوامرك المقدسة، كمسرة الله أبيك الصالح." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'heading', text: { en: "Psalm of the Gospel", ar: "المزمور" } },
      { kind: 'rubric', text: { en: "A psalm of David, chanted before the Holy Gospel", ar: "A psalm of David, chanted before the Holy Gospel" } },
      { kind: 'rubric', text: { en: "The Psalm of the day, chanted before the Gospel.", ar: "مزمور اليوم، يُرتل قبل الإنجيل." } },
      { kind: 'heading', text: { en: "The Holy Gospel", ar: "الإنجيل" } },
      { kind: 'rubric', text: { en: "The Holy Gospel — the reading appointed for this day.", ar: "الإنجيل المقدس — القراءة المعينة لهذا اليوم." } },
      { kind: 'heading', text: { en: "Gospel Response", ar: "مرد الإنجيل" } },
      { kind: 'prayer', text: { en: "Let us worship our Savior, the good Lover of Mankind, for He had compassion on us, He has come and saved us.", ar: "فلنسجد لمخلصنا، محب البشر الصالح، لأنه تراءف علينا، أتى وخلصنا." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Intercede on our behalf, O the Lady of us all the Theotokos, Mary the Mother of our Savior, that He may forgive us our sins.", ar: "إشفعي فينا أمام الرب، يا سيدتنا كلنا السيدة والدة الإله، مريم أم مخلصنا، ليغفر لنا خطايانا." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Pray to the Lord on our behalf, O beholder of God the Evangelist, Abba Mark the Apostle, that He may forgive us our sins.", ar: "أطلب من الرب عنا، يا ناظر الإله الإنجيلي، مارمرقس الرسول، ليغفر لنا خطايانا." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "For blessed be the Father and the Son, and the Holy Spirit, the perfect Trinity, we worship Him and glorify Him.", ar: "لأنه مبارك الآب والإبن، والروح القدس، الثالوث الكامل، نسجد له ونمجده." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'heading', text: { en: "Litany for the Peace", ar: "أوشية السلام" } },
      { kind: 'litany', text: { en: "Again, let us ask God the Pantocrator, the Father of our Lord, God, and Savior Jesus Christ.", ar: "وأيضاً فلنسأل الله الضابط الكل، أبا ربنا وإلهنا ومخلصنا يسوع المسيح." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "We ask and entreat Your goodness, O Lover of Mankind, remember, O Lord, the peace of Your one, only, holy, catholic, and apostolic Church—", ar: "نسأل ونطلب من صلاحك يا محب البشر، أُذكر يا رب سلام كنيستك الواحدة الوحيدة المقدسة الجامعة الرسولية." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Pray for the peace of the one, holy, catholic, and apostolic orthodox Church of God.", ar: "صلوا من أجل سلام الواحدة المقدسة الجامعة الرسولية كنيسة الله الأرثوذكسية." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'litany', text: { en: "Lord have mercy.", ar: "يا ربُّ إرحَم." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'litany', text: { en: "that which exists from one end of the world to the other.", ar: "هذه الكائنة من أقاصي المسكونة إلى أقاصيها." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'heading', text: { en: "Litany for the Fathers", ar: "أوشية الآباء" } },
      { kind: 'litany', text: { en: "Remember, O Lord, our patriarch, the honored father and high priest, Pope Abba (Tawadros II).", ar: "أُذكر يا رب بطريركنا الأب المكرم رئيس الكهنة البابا المعظم أنبا (تواضروس الثاني)،" }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "and his spiritual brothers, the Patriarch of Antioch Mar Ignatius (…), and the Patriarch of Eritrea Abouna (…).", ar: "وأخوية الروحيين مار إغناطيوس (...) بطريرك أنطاكية وأبونا (...) بطريرك إريتريا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'rubric', text: { en: "In the presence of a bishop:", ar: "في حضور الأب الأسقف:" } },
      { kind: 'litany', text: { en: "and his partner in the liturgy, our father the bishop (metropolitan), Abba (…).", ar: "وشريكة في الخدمة الرسولية أبينا الأسقف (المطران) الأنبا (...)." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Pray for our high priest, Pope Abba (Tawadros II), pope and patriarch and archbishop of the great city of Alexandria,", ar: "صلوا من أجل رئيس كهنتنا البابا أنبا (تواضروس الثاني)، بابا وبطريرك ورئيس أساقفة المدينة العظمى الاسكندرية،" }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'litany', text: { en: "and his spiritual brothers, the Patriarch of Antioch Mar Ignatius (…), and the Patriarch of Eritrea Abouna (…).", ar: "وأخوية الروحيين مار إغناطيوس (...) بطريرك أنطاكية وأبونا (...) بطريرك إريتريا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'rubric', text: { en: "In the presence of a bishop:", ar: "في حضور الأب الأسقف:" } },
      { kind: 'litany', text: { en: "and his partner in the liturgy, our father the bishop (metropolitan), Abba (…),", ar: "وشريكة في الخدمة الرسولية أبينا الأسقف (المطران) الأنبا (...)،" }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'rubric', text: { en: "And concludes with:", ar: "وينهي:" } },
      { kind: 'litany', text: { en: "and for our orthodox bishops.", ar: "وسائر أساقفتنا الأرثوذكسيين." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Lord have mercy.", ar: "يا ربُّ إرحَم." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'litany', text: { en: "In keeping, keep them for us for many years and peaceful times.", ar: "حفظاً إحفظهم لنا سنين كثيرة وأزمنة سلامية." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'heading', text: { en: "Litany for the Place", ar: "أوشية الموضع" } },
      { kind: 'litany', text: { en: "Remember, O Lord, the salvation of this, Your holy place, and every place, and every monastery of our orthodox fathers—", ar: "أُذكر يا رب خلاص هذا الموضع المقدس الذي لك، وكل المواضع وكل أديرة آبائنا الأرثوذكسيين." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Pray for the salvation of the world and of this city of ours, and of all cities, districts, island, and monasteries.", ar: "صلوا من أجل خلاص هذا العالم ومدينتنا هذة، وسائر المدن والأقاليم والجزائر والأديرة." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'litany', text: { en: "Lord have mercy.", ar: "يا ربُّ إرحَم." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'litany', text: { en: "and every city and every region, and the villages and all their adornments.", ar: "وكل مدينة، وكل كورة، والقرى وكل زينتها." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "And save us all from famine, plagues, earthquakes, drowning, fire, captivity by barbarians, the sword of the stranger, and the rising up of heretics.", ar: "ونجنا كلنا من الغلاء، والوباء، والزلزال، والغرق، والحريق، وسبي البربر، ومن سيف الغريب، ومن قيام الهراطقة." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Lord have mercy.", ar: "يا ربُّ إرحَم." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'heading', text: { en: "Litany for the Nature", ar: "أوشية الطبيعة" } },
      { kind: 'rubric', text: { en: "Season of the waters", ar: "موسم المياه" } },
      { kind: 'heading', text: { en: "Litany of the Waters", ar: "أوشية المياه" } },
      { kind: 'litany', text: { en: "Graciously accord, O Lord, to bless the waters of the river this year.", ar: "تفضل يا رب مياه النهر في هذه السنة، باركها." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Pray for the rising of the waters of the rivers this year, that Christ our God may bless them and raise them according to their measure, that He may give joy to the face of the earth, sustain us, the sons of men, save the cattle, and forgive us our sins.", ar: "أُطلبوا عن صعود مياه الأنهار في هذا السنة، لكيْ يباركها المسيح إلهنا، ويصعدها كمقدارها، ويفرِّح وجه الأرض، ويعولنا نحن بني البشر، ويعطي النجاة للبهائم، ويغفر لنا خطايانا." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'litany', text: { en: "Lord have mercy (3).", ar: "يا ربُّ إرحَم (3)." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'rubric', text: { en: "Season of the plants", ar: "موسم الزروع" } },
      { kind: 'heading', text: { en: "Litany of the Plants", ar: "أوشية الزروع" } },
      { kind: 'litany', text: { en: "Graciously accord, O Lord, to bless the seeds, the herbs, and the plants of the field this year.", ar: "تفضل يا رب، الزروع والعشب ونبات الحقل في هذه السنة، باركها." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Pray for the seeds, the herbs, and the plants of the field this year, that Christ our God may bless them to grow and multiply unto perfection with great fruit, have compassion on His creation which His hands have made, and forgive us our sins.", ar: "أُطلبوا عن الزروع والعشب ونبات الحقل، في هذه السنة، لكيْ يباركها المسيح إلهنا، لتنمو وتكثر إلى أن تكمل بثمرة عظيمة، ويتحنن على جبلته التي صنعتها يداه، ويغفر لنا خطايانا." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'litany', text: { en: "Lord have mercy (3).", ar: "يا ربُّ إرحَم (3)." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'rubric', text: { en: "Season of the fruits", ar: "موسم الثمار" } },
      { kind: 'heading', text: { en: "Litany of the Fruits", ar: "أوشية الثمار" } },
      { kind: 'litany', text: { en: "Graciously accord, O Lord, to bless the air of heaven and the fruits of the earth this year.", ar: "تفضل يا رب أهوية السماء وثمرات الأرض، في هذه السنة، باركها." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Pray for the air of heaven, the fruits of the earth, the trees, the vines, and for every fruit-bearing tree in all the world, that Christ our God may bless them, bring them to perfection in peace without harm, and forgive us our sins.", ar: "أُطلبوا عن أهوية السماء، وثمرات الأرض والشجر والكروم، وكل شجرة مثمرة في كل المسكونة، لكي يباركها المسيح إلهنا، ويكملها سالمة بغير ألم، ويغفر لنا خطايانا." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'litany', text: { en: "Lord have mercy (3).", ar: "يا ربُّ إرحَم (3)." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'litany', text: { en: "Raise them to their measure according to Your grace. Give joy to the face of the earth. May its furrows be abundantly watered and its fruits be plentiful.", ar: "اصعِدْها كمقدارِها كنعمَتِكَ، فَرِّحْ وجهَ الأرضِ، ليُرْوَ حرثُها ولتكثرَ أثمارُها." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Prepare it for sowing and harvesting. Manage our lives as deemed fit.", ar: "أعِدَّها للزرعِ والحصادِ، ودَبِّر حياتَنا كما يليق." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Bless the crown of the year with Your goodness for the sake of the poor of Your people, the widow, the orphan, the traveler, the stranger, and for the sake of all of us who entreat You and seek Your holy name.", ar: "بَارِكْ إكليلَ السنةِ بصلاحِكَ، من أجلِ فقراءِ شعبِكَ، من أجلِ الأرملةِ واليتيمِ والغريبِ والضيفِ، ومن أجلِنا كُلِّنا نحنُ الذين نرجوكَ ونطلبُ إسمَكَ القدوس." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "For the eyes of everyone wait upon You, for You give them their food in due season.", ar: "لأن أعينَ الكلِّ تترجاكَ، لأنَّكَ أنتَ الذي تُعطِيهم طعامَهم في حينٍ حسنٍ." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Deal with us according to Your goodness, O You who give food to all flesh. Fill our hearts with joy and gladness, that we too, having sufficiency in everything always, may abound in every good deed.", ar: "إصنع معنا حَسَبَ صلاحِكَ، يا مُعطِياً طعاماً لكلِّ جسدٍ. املأ قلوبَنا فرحاً ونعيماً، لكي نحنُ أيضاً إذ تكونَ لنا الكفايةُ في كلِّ شيءٍ، كلَّ حينٍ، نزدادَ في كلِّ عملٍ صالحٍ." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'heading', text: { en: "Litany for the Assemblies", ar: "أوشية الإجتماعات" } },
      { kind: 'litany', text: { en: "Again, let us ask God the Pantocrator, the Father of our Lord, God, and Savior Jesus Christ.", ar: "وأيضاً فلنسأل الله الضابط الكل، أبا ربنا وإلهنا ومخلصنا يسوع المسيح." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "We ask and entreat Your goodness, O Lover of Mankind, remember, O Lord, our assemblies.", ar: "نسأل ونطلب من صلاحك يا محب البشر، أُذكر يا رب إجتماعاتنا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Bless them.", ar: "باركها." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Pray for this holy church and for our assemblies.", ar: "صلوا من أجل هذه الكنيسة المقدسة وإجتماعاتنا." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'litany', text: { en: "Lord have mercy.", ar: "يا ربُّ إرحَم." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'litany', text: { en: "Grant that they may be to us without obstacle or hindrance, that we may hold them according to Your holy and blessed will:", ar: "أعط أن تكون لنا بغير مانع ولا عائق، لنصنعها كمشيئتك المقدسة الطوباوية." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "houses of prayer, houses of purity, houses of blessing. Grant them to us, O Lord, and Your servants who shall come after us, forever.", ar: "بيوت صلاة، بيوت طهارة، بيوت بركة، أنعم بها لنا يا رب، ولعبيدك الآتين بعدنا إلى الأبد." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'rubric', text: { en: "The following may be said:", ar: "يمكن يقال الآتي:" } },
      { kind: 'litany', text: { en: "The worship of idols, utterly uproot from the world.", ar: "عبادة الأوثان بتمامها، إقلعها من العالم." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Satan and all his evil powers, trample and humiliate under our feet speedily.", ar: "الشيطان وكل قواته الشريرة، إسحقهم وأذلهم تحت أقدامنا سريعاً." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "All offenses and their instigators, do abolish. May all dissensions of corrupt heresies cease.", ar: "الشكوك وفاعليها إبطلهم. ولينقض إفتراقات فساد البدع." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "The enemies of Your holy Church, O Lord, as at all times, now also humiliate.", ar: "أعداء كنيستك المقدسة يا رب، مثل كل زمان، الآن أيضاً أذلهم." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Strip their vanity, show them their weakness speedily.", ar: "حل تعاظمهم، عرفهم ضعفهم سريعاً." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Bring to naught their envy, their intrigues, their madness, their wickedness, and their slander, which they commit against us.", ar: "أبطل حسدهم، وسعايتهم، وجنونهم، وشرهم، ونميمتهم التي يصنعونها فينا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "O Lord, bring them all to no avail. Disperse their counsel, O God, who dispersed the counsel of Ahithophel.", ar: "يا رب إجعلهم كلهم كلا شئ، وبدد مشورتهم يا الله الذي بدد مشورة أخيتوفل." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Amen.", ar: "آمين." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'litany', text: { en: "Lord have mercy.", ar: "يا ربُّ إرحَم." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'rubric', text: { en: "Then the following is said:", ar: "ثم يكمل بالآتي:" } },
      { kind: 'litany', text: { en: "Arise, O Lord God, let all Your enemies be scattered, and let all who hate Your holy name flee before Your face.", ar: "قم أيها الرب الإله. وليتفرق جميع أعدائك. وليهرب من قدام وجهك كل مبغضي إسمك القدوس." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "But let Your people be in blessing, thousands of thousands and ten thousand times ten thousand doing Your will,", ar: "وأما شعبك فليكن بالبركة، ألوف ألوف وربوات ربوات، يصنعون إرادَتك." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "by the grace, compassion and love-of-mankind, of Your only-begotten Son, our Lord, God, and Savior, Jesus Christ.", ar: "بالنعمة والرأفات ومحبة البشر اللواتي لإبنك الوحيد ربنا وإلهنا ومخلصنا يسوع المسيح." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Through whom the glory, the honor, the dominion, and the worship are due unto You, with Him and the Holy Spirit, the Giver of Life, who is of one essence with You, now and at all times, and unto the age of all ages. Amen.", ar: "هذا الذي من قبله المجد والإكرام والعزة والسجود تليق بك معه، مع الروح القدس المحيي المساوي لك. الآن وكل أوان وإلى دهر الدهور. آمين." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Make us worthy to pray thankfully:", ar: "وإجعلنا مستحقين أن نقول بشكر:" }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "“Our Father who art in heaven…”", ar: "\"أبانا الذي في السموات...\"" }, label: { en: "People", ar: "الشعب" } },
      { kind: 'litany', text: { en: "In Christ Jesus our Lord.", ar: "بالمسيح يسوع ربنا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'heading', text: { en: "Our Father", ar: "أبانا الذي" } },
      { kind: 'prayer', text: { en: "Our Father who art in heaven, hallowed be Thy name. Thy kingdom come. Thy will be done, on earth as it is in heaven. Give us this day our daily bread; and forgive us our trespasses, as we forgive those who trespass against us; and lead us not into temptation, but deliver us from the evil one. In Christ Jesus our Lord, for Thine is the kingdom and the power and the glory forever. Amen.", ar: "أبانا الذي في السموات، ليتقدس إسمك. ليأت ملكوتك. لتكن مشيئتك، كما في السماء كذلك على الأرض. خبزنا كفافنا أعطنا اليوم. وأغفر لنا ذنوبنا، كما نغفر نحن أيضاً للمذنبين إلينا. ولا تدخلنا في تجربة، لكن نجنا من الشرير. بالمسيح يسوع ربنا، لأن لك الملك والقوة والمجد إلى الأبد. آمين." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'heading', text: { en: "The Conclusion", ar: "الختام" } },
      { kind: 'prayer', text: { en: "Amen.", ar: "آمين." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Lord have mercy (3).", ar: "يا ربُّ إرحَم (3)." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Amen, alleluia. Glory to the Father and the Son and the Holy Spirit, now and ever and unto the age of all ages, amen.", ar: "آمين، هلليلويا. المجد للآب والإبن والروح القدس، الآن وكل أوان وإلى دهر الدهور، آمين." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "We proclaim saying: “O our Lord Jesus Christ.", ar: "نصرخ قائلين: \"يا ربنا يسوع المسيح." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Bless the air of heaven, the waters of the river, and the seeds and the herbs.", ar: "بارك أهوية السماء، مياه النهر والزروع والعشب." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "May Your mercy and Your peace be a fortress to Your people.", ar: "ولتكن رحمتك وسلامك حصناً لشعبك." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Save us and have mercy upon us.”", ar: "خلصنا وإرحمنا.\"" }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Lord have mercy, Lord have mercy, Lord bless amen. Bless me, bless me, behold the repentance, forgive me, say the blessing.", ar: "يا ربُّ إرحَم، يا ربُّ إرحَم، يا رب بارك آمين. باركوا عليَّ، باركوا عليَّ، ها مطانية، إغفروا لي، قُل البركة." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'heading', text: { en: "The Short Blessing", ar: "البركة القصيرة" } },
      { kind: 'prayer', text: { en: "May God have compassion upon us, bless us, manifest His face upon us, and have mercy upon us.", ar: "الله يترأف علينا ويباركنا، ويظهر وجهه علينا ويرحمنا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "O Lord, save Your people, bless Your inheritance, shepherd them, and raise them up forever.", ar: "يا رب خلص شعبك. بارك ميراثك. إرعهم وإرفعهم إلى الأبد." } },
      { kind: 'prayer', text: { en: "Exalt the horn of Christians through the power of the life-giving Cross", ar: "إرفع شأن المسيحيين بقوة الصليب المحيي." } },
      { kind: 'prayer', text: { en: "and through the supplications and prayers which our Lady, the Lady of us all, the holy Theotokos, Saint Mary, makes for us.", ar: "بالسؤالات والطلبات التي تصنعها عنا كل حين سيدتنا وملكتنا كلنا والدة الإله القديسة الطاهرة مريم." } },
      { kind: 'prayer', text: { en: "And [through the supplications and prayers of] the three great holy luminaries Michael, Gabriel, and Raphael;", ar: "والثلاثة العظماء المنيرون الأطهار ميخائيل وغبريال وروفائيل." } },
      { kind: 'prayer', text: { en: "the four incorporeal creatures; the twenty-four priests; all the heavenly orders;", ar: "والأربعة الحيوانات غير المتجسدين، والأربعة والعشرون قسيساً وكل الطغمات السمائية." } },
      { kind: 'prayer', text: { en: "Saint John the Baptist; the hundred and forty-four thousand; my masters and fathers the apostles; the three holy youths; Saint Stephen;", ar: "والقديس يوحنا المعمدان، والمائة والأربعة والأربعين ألفاً، وسادتي الآباء الرسل، والثلاثة فتية القديسين، والقديس إستفانوس." } },
      { kind: 'prayer', text: { en: "the beholder-of-God, Saint Mark the Evangelist, the apostle and martyr;", ar: "وناظر الإله الإنجيلي مرقس الرسول القديس والشهيد." } },
      { kind: 'prayer', text: { en: "Saint George; Saint Theodore; Philopater Mercurius; Saint Abba Mina; and the whole choir of the martyrs;", ar: "والقديس جرجس، والقديس تادرس، وفيلوباتير مرقوريوس، والقديس أبا مينا، وكل مصاف الشهداء." } },
      { kind: 'prayer', text: { en: "our righteous father, the great Abba Anthony; the righteous Abba Paul; the three saints Abba Macarii;", ar: "وأبونا الصديق العظيم الأنبا أنطونيوس، والبار أنبا بولا، والثلاثة أنبا مقارات القديسون." } },
      { kind: 'prayer', text: { en: "our father Abba John; our father Abba Pishoi; our father Abba Paul of Tammoh; our Roman fathers Maximus and Dometius; our father Abba Moses; the Forty-nine Martyrs;", ar: "وأبونا أنبا يوحنا، وأبونا أنبا بيشوي، وأبونا أنبا بولا الطموهي، وأبوانا الروميان مكسيموس ودوماديوس، وأبونا انبا موسى، والتسعة والأربعون شهيداً." } },
      { kind: 'prayer', text: { en: "the whole choir of the cross-bearers; the just; the righteous; all the wise virgins; the angel of this blessed night.", ar: "وكل مصاف لباس الصليب والأبرار والصديقون، وجميع العذارى الحكيمات، وملاك هذه الليلة المباركة." } },
      { kind: 'rubric', text: { en: "(The patron saint of the church is mentioned, followed by the saint(s) of the day.)", ar: "ههنا يذكر اسم صاحب الكنيسة ثم يقول:" } },
      { kind: 'prayer', text: { en: "and the blessing of the holy Theotokos, first and last.", ar: "وبركة والدة الإله القديسة الطاهرة مريم أولاً وآخراً." } },
      { kind: 'rubric', text: { en: "On Sundays", ar: "في أيام الآحاد" } },
      { kind: 'prayer', text: { en: "and the blessing of the Lord’s Day of our good Savior.", ar: "وبركة يوم الأحد الذي لمخلصنا الصالح." } },
      { kind: 'prayer', text: { en: "May their holy blessing, their grace, their power, their gift, their love, and their help rest upon us all forever. Amen.", ar: "بركتهم المقدسة، ونعمتهم، وقوتهم، وهبتهم، ومحبتهم، ومعونتهم تكون معنا كلنا إلى الآبد. آمين." } },
      { kind: 'rubric', text: { en: "The priest casts water on the congregation, saying,", ar: "ويرش الكاهن الشعب ويقول:" } },
      { kind: 'prayer', text: { en: "O Christ our God—", ar: "أيها المسيح إلهنا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Amen. So be it.", ar: "آمين يكون." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "O King of peace, grant us Your peace, establish for us Your peace, and forgive us our sins. For Yours is the power, the glory, the blessing, and the might, forever. Amen.", ar: "يا ملك السلام، أعطينا سلامك. قرر لنا سلامك وإغفر لنا خطايانا. لأن لك القوة والمجد والبركة والعزة إلى الأبد. آمين." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Make us worthy to pray thankfully:", ar: "وإجعلنا مستحقين أن نقول بشكر:" } },
      { kind: 'prayer', text: { en: "“Our Father who art in heaven…”", ar: "\"أبانا الذي في السموات...\"" }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "The grace of our Lord, God, and Savior Jesus Christ be with you all.", ar: "ونعمة ربنا وإلهنا ومخلصنا يسوع المسيح مع جميعكم." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Go in peace. The Lord be with you all.", ar: "إمضوا بسلام. الرب مع جميعكم." } },
      { kind: 'rubric', text: { en: "Or he says:", ar: "أو يقول:" } },
      { kind: 'prayer', text: { en: "The love of God the Father; the grace of the only-begotten Son, our Lord, God, and Savior Jesus Christ; and the communion and gift of the Holy Spirit be with you all. Go in peace. The peace of the Lord be with you all.", ar: "محبة الله الآب، ونعمة الإبن الوحيد، ربنا وإلهنا وملكنا ومخلصنا يسوع المسيح، وشركة وموهبة الروح القدس تكون مع جميعكم. إمضوا بسلام، سلام الرب مع جميعكم." } },
      { kind: 'prayer', text: { en: "And with your spirit.", ar: "مع روحك أيضاً." }, label: { en: "People", ar: "الشعب" } }
    ],
  },
  {
    id: "incense-morning",
    title: { en: "Morning Raising of Incense", ar: "رفع بخور باكر" },
    blocks: [
      { kind: 'note', text: { en: "The Matins offering of incense, prayed each morning", ar: "صلاة رفع بخور باكر" } },
      { kind: 'heading', text: { en: "The Thanksgiving Prayer", ar: "صلاة الشكر" } },
      { kind: 'prayer', text: { en: "Have mercy on us, O God, the Father, the Pantocrator. All-Holy Trinity, have mercy on us.", ar: "إرحمنا يا الله الآب ضابط الكل. أيها الثالوث القدوس إرحمنا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "O Lord, God of the powers, be with us, for we have no helper in our tribulations and afflictions but You.", ar: "أيها الرب إله القوات كن معنا، لأنه ليس لنا معين في شدائدنا وضيقاتنا سواك." } },
      { kind: 'prayer', text: { en: "Make us worthy to pray thankfully:", ar: "وإجعلنا مستحقين أن نقول بشكر:" } },
      { kind: 'prayer', text: { en: "Our Father who art in heaven, hallowed be Thy name. Thy kingdom come. Thy will be done, on earth as it is in heaven. Give us this day our daily bread; and forgive us our trespasses, as we forgive those who trespass against us; and lead us not into temptation, but deliver us from the evil one. In Christ Jesus our Lord, for Thine is the kingdom and the power and the glory forever. Amen.", ar: "أبانا الذي في السموات، ليتقدس إسمك. ليأت ملكوتك. لتكن مشيئتك، كما في السماء كذلك على الأرض. خبزنا كفافنا أعطنا اليوم. وأغفر لنا ذنوبنا، كما نغفر نحن أيضاً للمذنبين إلينا. ولا تدخلنا في تجربة، لكن نجنا من الشرير. بالمسيح يسوع ربنا، لأن لك الملك والقوة والمجد إلى الأبد. آمين." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "In Christ Jesus our Lord.", ar: "بالمسيح يسوع ربنا." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Pray.", ar: "صلوا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Stand up for prayer.", ar: "للصلاة قفوا." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'prayer', text: { en: "Peace be with all.", ar: "السلام لجميعكم." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "And with your spirit.", ar: "ولروحك أيضاً." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Let us give thanks to the beneficent and merciful God, the Father of our Lord, God, and Savior Jesus Christ.", ar: "فلنشكر صانع الخيرات، الرحوم الله أبا ربنا وإلهنا ومخلصنا يسوع المسيح." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "For He has covered us, helped us, guarded us, accepted us to Himself, spared us, supported us, and has brought us to this hour.", ar: "لأنه سترنا وأعاننا وحفظنا وقبلنا إليه وشفق علينا وعضدنا وأتى بنا إلى هذه الساعة." } },
      { kind: 'prayer', text: { en: "Let us also ask Him, the Lord our God, the Pantocrator, to guard us in all peace this holy day and all the days of our life.", ar: "هو أيضاً فلنسأله أن يحفظنا في هذا اليوم المقدس، وكل أيام حياتنا بكل سلام، ضابط الكل الرب إلهنا." } },
      { kind: 'prayer', text: { en: "Let us pray.", ar: "صلوا." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'prayer', text: { en: "Lord have mercy.", ar: "يا ربُّ إرحَم." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "O Master, Lord, God the Pantocrator, the Father of our Lord, God, and Savior Jesus Christ, we thank You for everything, concerning everything, and in everything.", ar: "أيها السيد الرب الإله ضابط الكل أبو ربنا وإلهنا ومخلصنا يسوع المسيح، نشكرك على كل حال ومن أجل كل حال وفي كل حال." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "For You have covered us, helped us, guarded us, accepted us to Yourself, spared us, supported us, and have brought us to this hour.", ar: "لأنك سترتنا وأعنتنا وحفظتنا وقبلتنا إليك وشفقت علينا وعضدتنا وأتيت بنا إلى هذه الساعة." } },
      { kind: 'prayer', text: { en: "Pray that God may have mercy and compassion on us, hear us, help us and accept the supplications and prayers of His saints, for that which is good on our behalf at all times*; and forgive us our sins.", ar: "أُطلبوا لكي يرحمنا الله، ويتراءف علينا ويسمعنا، ويعيننا، ويقبل سؤالات وطلبات قديسيه منهم بالصلاح عنا في كل حين* ويغفر لنا خطايانا." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'rubric', text: { en: "* In the presence of a bishop, the following part is added:", ar: "* في حضور الأب الأسقف، يقول الشماس هذه القطعة:" } },
      { kind: 'prayer', text: { en: "And to keep the life and standing of our honored father, Pope Abba (…) and his partner in the liturgy, our father the bishop (metropolitan), Abba (...);", ar: "وأن يحفظ حياة وقيام أبينا المكرم البابا الأنبا (...)، وشريكه في الخدمة الرسولية أبينا الأسقف (المطران) أنبا (...)." } },
      { kind: 'prayer', text: { en: "Lord have mercy.", ar: "يا ربُّ إرحَم." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Therefore, we ask and entreat Your goodness, O Lover of Mankind, grant us to complete this holy day and all the days of our life in all peace with Your fear.", ar: "من أجل هذا نسأل ونطلب من صلاحك يا محب البشر، إمنحنا أن نكمل هذا اليوم المقدس وكل أيام حياتنا بكل سلام مع مخافتك." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "All envy, all temptation, all the work of Satan, the counsel of wicked men and the rising up of enemies, hidden and manifest, take them away from us, and from all Your people,", ar: "كل حسد وكل تجربة وكل فعل الشيطان ومؤامرة الناس الأشرار وقيام الأعداء الخفيين والظاهرين. إنزعها عنا، وعن سائر شعبك،" } },
      { kind: 'prayer', text: { en: "and from this church,", ar: "وعن هذه الكنيسة،" } },
      { kind: 'prayer', text: { en: "(and from this table,)", ar: "(وعن هذه المائدة،)" } },
      { kind: 'prayer', text: { en: "and from this, Your holy place.", ar: "وعن موضعك المقدس هذا." } },
      { kind: 'prayer', text: { en: "But those things which are good and profitable do provide for us, for it is You who have given us the authority to tread on serpents and scorpions, and upon all the power of the enemy.", ar: "أما الصالحات والنافعات فارزقنا إياها، لأنك أنت الذي أعطيتنا السلطان أن ندوس على الحيات والعقارب وكل قوة العدو." } },
      { kind: 'prayer', text: { en: "And lead us not into temptation, but deliver us from the evil one, by the grace, compassion and love-of-mankind, of Your only-begotten Son, our Lord, God, and Savior, Jesus Christ.", ar: "ولا تدخلنا في تجربة، لكن نجنا من الشرير. بالنعمة والرأفات ومحبة البشر اللواتي لإبنك الوحيد، ربنا وإلهنا ومخلصنا يسوع المسيح." } },
      { kind: 'prayer', text: { en: "Through whom the glory, the honor, the dominion, and the worship are due unto You, with Him and the Holy Spirit, the Giver of Life, who is of one essence with You, now and at all times, and unto the age of all ages. Amen.", ar: "هذا الذي من قبله المجد والإكرام والعزة والسجود تليق بك معه، مع الروح القدس المحيي المساوي لك. الآن وكل أوان وإلى دهر الدهور. آمين." } },
      { kind: 'rubric', text: { en: "(The priest raises the incense while the Verses of Cymbals are chanted)", ar: "(يرفع الكاهن بخور وتُرتَّل أرباع الناقوس)" } },
      { kind: 'heading', text: { en: "Verses of Cymbals", ar: "أرباع الناقوس" } },
      { kind: 'prayer', text: { en: "Lord have mercy.", ar: "يارب إرحم." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'rubric', text: { en: "Sunday tune (Watos)", ar: "اللحن الواطس (الأحد)" } },
      { kind: 'prayer', text: { en: "We worship the Father and the Son, and the Holy Spirit, the holy and co-essential Trinity.", ar: "نسجد للاب والابن والروح القدس الثالوث القدوس المساوي في الجوهر." } },
      { kind: 'prayer', text: { en: "Hail to the Church, the house of the angels, hail to the Virgin, who gave birth to our Savior.", ar: "السلام للكنيسة بيت الملائكة السلام للعذراء التي ولدت مخلصنا." } },
      { kind: 'rubric', text: { en: "Weekday tune (Adam)", ar: "اللحن الآدام (أيام الأسبوع)" } },
      { kind: 'prayer', text: { en: "O come let us worship, the Holy Trinity, the Father and the Son, and the Holy Spirit.", ar: "تعالوا فلنسجد، للثالوث القدوس، الذي هو الأب والإبن، والروح القدس." } },
      { kind: 'prayer', text: { en: "We the Christian people, for He is our true God.", ar: "نحن الشعوب المسيحيين، لأن هذا هو إلهنا الحقيقي." } },
      { kind: 'prayer', text: { en: "We have hope, in Saint Mary, that God will have mercy upon us, through her intercessions.", ar: "لنا رجاء، في القديسة مريم، الله يرحمنا، بشفاعاتها." } },
      { kind: 'prayer', text: { en: "All calmness, in the world, is through the prayers, of Saint Mary the Virgin.", ar: "كل هدوء، في العالم، من قبل صلاة، القديسة مريم العذراء." } },
      { kind: 'prayer', text: { en: "Hail to you O Mary, the beautiful dove, who gave birth to us, God the Word.", ar: "السلام لك يا مريم الحمامة الحسنة التي ولدت لنا الله الكلمة." } },
      { kind: 'prayer', text: { en: "Hail to you O Mary, a holy hail, hail to you O Mary, the Mother of the Holy One.", ar: "السلام لك يا مريم سلام مقدس السلام لك يا مريم ام القدوس." } },
      { kind: 'prayer', text: { en: "Hail to her who found grace, the Lord is with you, hail to her who received from the angel, the joy of the world.", ar: "السلام للتى وجدت نعمة الرب معك السلام للتى قبلت من الملاك فرح العالم." } },
      { kind: 'prayer', text: { en: "Hail to Michael, the great archangel, hail to Gabriel, the Announcer.", ar: "السلام لميخائيل رئيس الملائكة العظيم. السلام لغبريال المبشر المختار." } },
      { kind: 'prayer', text: { en: "Hail to the Cherubim, hail to the Seraphim, hail to all the heavenly orders.", ar: "السلام للشاروبيم السلام للسيرافيم السلام لجميع الطغمات السمائية." } },
      { kind: 'prayer', text: { en: "Hail to John, the great forerunner, hail to the priest, the relative of Emmanuel.", ar: "السلام ليوحنا السابق العظيم السلام للكاهن نسيب عمانوئيل." } },
      { kind: 'prayer', text: { en: "Hail to my masters and fathers, the Apostles, hail to the Disciples, of our Lord Jesus Christ.", ar: "السلام لساداتي الاباء الرسل. السلام لتلاميذ ربنا يسوع المسيح." } },
      { kind: 'prayer', text: { en: "Hail to you O martyr, hail to the Evangelist, hail to the Apostle, Abba Mark the beholder of God.", ar: "السلام لك ايها الشهيد السلام للانجيلي السلام للرسول مرقس ناظر الاله." } },
      { kind: 'rubric', text: { en: "When commemorating the martyrs", ar: "عند تذكار الشهداء" } },
      { kind: 'prayer', text: { en: "Hail to you O martyrs, hail to the courageous heroes, hail to the struggle-mantled, my lord prince George, Theodore the general, Philopater Mercurius, Abba Mina of Fayat.", ar: "السلام لكم أيها الشهداء، السلام للشجعان الأبطال، السلام للمجاهدين، سيدي الملك جيؤرجيوس، تيؤدوروس الإسفهسلار، مرقوريوس محب الآب، أبا مينا البياضي." } },
      { kind: 'prayer', text: { en: "Jesus Christ the same yesterday, today, and forever, in one hypostasis, we worship and glorify Him.", ar: "يسوع المسيح هو هو، أمساً واليوم وإلى الأبد، اقنوم واحد، نسجد له ونمجده." } },
      { kind: 'prayer', text: { en: "O King of peace, grant us Your peace, establish for us Your peace, and forgive us our sins.", ar: "يا ملِكَ السلامِ، أعطِنا سلامَكَ، قرِّرْ لنا سلامَكَ، واغفِرْ لنا خطايانا." } },
      { kind: 'prayer', text: { en: "Disperse the enemies, of the Church, and fortify her, that she may not be shaken forever.", ar: "فرِّقْ أعداءَ الكنيسةِ، وحصِّنْها، فلا تتزعزعُ، إلى الأبدِ." } },
      { kind: 'prayer', text: { en: "Emmanuel our God, is now in our midst, with the glory of His Father, and the Holy Spirit.", ar: "عِمَّانوئيلُ إلهُنا، في وسَطِنا الآنَ، بمجدِ أبيهِ، والروحِ القُدُسِ." } },
      { kind: 'prayer', text: { en: "May He bless us all, purify our hearts, and heal the sicknesses, of our souls and bodies.", ar: "ليباركَنا كلَّنا، ويطهِّرَ قلوبَنا، ويشفيَ أمراضَ، نفوسِنا وأجسادِنا." } },
      { kind: 'heading', text: { en: "Litany for the Sick", ar: "أوشية المرضى" } },
      { kind: 'rubric', text: { en: "A Matins litany, optional for vespers.", ar: "من أواشي باكر، وتُقال اختيارياً في العشية." } },
      { kind: 'litany', text: { en: "Pray.", ar: "صلوا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Stand up for prayer.", ar: "للصلاة قفوا." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'litany', text: { en: "Peace be with all.", ar: "السلام لجميعكم." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "And with your spirit.", ar: "ولروحك أيضاً." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'litany', text: { en: "Again, let us ask God the Pantocrator, the Father of our Lord, God, and Savior Jesus Christ.", ar: "وأيضاً فلنسأل الله الضابط الكل، أبا ربنا وإلهنا ومخلصنا يسوع المسيح." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "We ask and entreat Your goodness, O Lover of Mankind, remember, O Lord, the sick among Your people.", ar: "نسأل ونطلب من صلاحك يا محب البشر، أُذكر يا رب مرضى شعبك." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Pray for our fathers and our brethren who are sick with any sickness, whether in this place or in any place, that Christ our God may grant us, with them, health and healing, and forgive us our sins.", ar: "أُطلبوا عن آبائنا وإخوتنا المرضى بكل مرضٍ، إن كان في هذا المسكن أو بكل موضع، لكي المسيح إلهنا ينعم لنا ولهم بالعافية والشفاء، ويغفر لنا خطايانا." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'litany', text: { en: "Lord have mercy.", ar: "يا ربُّ إرحَم." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'litany', text: { en: "You have visited them with mercies and compassion, heal them.", ar: "تعهّدهم بالمراحم والرأفات إشفهم." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Take away from them and from us, all sickness and all disease; the spirit of sickness chase away.", ar: "إنزع عنهم وعنا كل مرضٍ وكل سقمٍ، وروح الأمراض أطرده." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Those who have long lain in sickness, raise up and comfort.", ar: "والذين أبطأوا مطروحين في الأمراض أقمهم وعزهم." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Those who are afflicted by unclean spirits, set them all free.", ar: "والمعذبين من الأرواح النجسة، اعتقهم جميعاً." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Those who are in prisons or dungeons, those who are in exile or captivity, and those who are held in bitter bondage, O Lord, set them all free and have mercy upon them.", ar: "الذين في السجون أو المطابق، أو الذين في النفي أو السبي أو المقبوض عليهم في عبودية مرة، يا رب اعتقهم جميعهم وإرحمهم." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "For You are He who loosens the bound and uplifts the fallen; the hope of those who have no hope and the help of those who have no helper; the comfort of the fainthearted; the harbor of those in the storm.", ar: "لأنك أنت الذي تحل المربوطين وتقيم الساقطين. رجاء من ليس له رجاء، ومعين من ليس له معين. عزاء صغيري القلوب، ميناء الذين في العاصف." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "All souls that are distressed or bound, grant them mercy, O Lord; grant them rest, grant them refreshment, grant them grace, grant them help, grant them salvation, grant them the forgiveness of their sins and their iniquities.", ar: "كل الأنفس المتضايقة، والمقبوض عليها. أعطها يا رب رحمةَ، أعطها نياحاً، أعطها برودة، أعطها نعمة، أعطها معونة، أعطها خلاصاً، أعطها غفران خطاياها وآثامها." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "As for us also, O Lord, the maladies of our souls, heal; and those of our bodies too, do cure.", ar: "ونحن أيضاً يا رب، أمراض نفوسنا، إشفها والتي لأجسادنا، عافها." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "O You, the true Physician of our souls and our bodies, the Bishop of all flesh, visit us with Your salvation.", ar: "أيها الطبيب الحقيقي الذي لأنفسنا، وأجسادنا، يا مدبر كل جسدٍ تعهدنا بخلاصك." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Lord have mercy.", ar: "يا ربُّ إرحَم." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'heading', text: { en: "Litany for the Travelers", ar: "أوشية المسافرين" } },
      { kind: 'rubric', text: { en: "A Matins litany, optional for vespers.", ar: "من أواشي باكر، وتُقال اختيارياً في العشية." } },
      { kind: 'litany', text: { en: "Pray.", ar: "صلوا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Stand up for prayer.", ar: "للصلاة قفوا." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'litany', text: { en: "Peace be with all.", ar: "السلام لجميعكم." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "And with your spirit.", ar: "ولروحك أيضاً." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'litany', text: { en: "We ask and entreat Your goodness, O Lover of Mankind, remember, O Lord, our fathers and our brethren who are traveling.", ar: "نسأل ونطلب من صلاحك يا محب البشر، أُذكر يا رب آباءنا وإخوتنا المسافرين." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Pray for our fathers and our brethren who are traveling, or those who intend to travel anywhere, that God may straighten all their ways, whether by sea, rivers, lakes, roads, air, or those who are traveling by any other means, that Christ our God may bring them back to their own homes in peace, and forgive us our sins.", ar: "أُطلبوا عن آبائنا وإخوتنا المسافرين، والذين يضمرون السفر في كل موضع، لكي يُسهل طرقهم أجمعين إن كان في البحر أو الأنهار أو البحيرات أو الطرق المسلوكة أو الجو أو المسافرين بكل نوع، لكي المسيح إلهنا يردهم إلى مساكنهم سالمين، ويغفر لنا خطايانا." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'litany', text: { en: "Lord have mercy.", ar: "يا ربُّ إرحَم." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'litany', text: { en: "And those who intend to travel anywhere, straighten all their ways, whether by sea, rivers, lakes, roads, air, or those who are traveling by any other means, everyone anywhere. Lead them into a haven of calm, a haven of safety.", ar: "والذين يضمرون السفر في كل مكان، سهل طرقهم أجمعين، إن كان في البحر أو الأنهار أو البحيرات أو الطرق المسلوكة أو الجو أو السالكين بكل نوع، كل أحد بكل موضع ردهم إلى ميناء هادئة، ميناء الخلاص." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Graciously accompany them in their departure and be their companion in their travel.", ar: "تفضل إصحبهم في الإقلاع، وإصحبهم في المسير." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Bring them back to their own, rejoicing with joy and safe in security.", ar: "ردهم إلى منازلهم بالفرح فرحين، وبالعافية معافين." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "In work, be a partner with Your servants in every good deed.", ar: "إشترك في العمل مع عبيدك في كل عمل صالح." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "As for us, O Lord, keep our sojourn in this life without harm, without storm, and undisturbed to the end.", ar: "ونحن أيضاً يا رب غربتنا في هذا العمر، إحفظها بغير مضرة ولا عاصف ولا قلق إلى الإنقضاء." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Lord have mercy.", ar: "يا ربُّ إرحَم." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'heading', text: { en: "Litany for the Oblations", ar: "أوشية القرابين" } },
      { kind: 'rubric', text: { en: "A Matins litany, optional for vespers.", ar: "من أواشي باكر، وتُقال اختيارياً في العشية." } },
      { kind: 'litany', text: { en: "We ask and entreat Your goodness, O Lover of Mankind, remember, O Lord, the sacrifices, the offerings and the thanksgivings of those who have offered to the honor and glory to Your holy name.", ar: "نسأل ونطلب من صلاحك يا محب البشر، أُذكر يا رب صعائد وقرابين وشكر الذين يقربون كرامة ومجداً لإسمك القدوس." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Pray for those who tend to the sacrifices, offerings, first-fruits, oil, incense, coverings, reading books, and altar vessels, that Christ our God may reward them in the heavenly Jerusalem, and forgive us our sins.", ar: "أُطلبوا عن المهتمين بالصعائد، والقرابين، والبكور، والزيت، والبخور، والستور، وكتب القراءة، وأواني المذبح، لكي المسيح إلهنا يكافئهم في أورشليم السمائية، ويغفر لنا خطايانا." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'litany', text: { en: "Lord have mercy.", ar: "يا ربُّ إرحَم." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'litany', text: { en: "Receive them upon Your holy, rational altar of heaven as a sweet savor of incense before Your greatness in the heavens, through the service of Your holy angels and archangels.", ar: "إقبلها إليك على مذبحك المقدس، الناطق السمائي رائحة بخور، تدخل إلى عظمتك التي في السموات. بواسطة خدمة ملائكتك ورؤساء ملائكتك المقدسين." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "As You have received the gifts of the righteous Abel, the sacrifice of our father Abraham and the two mites of the widow,", ar: "وكما قبلت إليك قرابين هابيل الصديق، وذبيحة أبينا إبراهيم، وفلسي الأرملة." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "so also receive the thank offerings of Your servants, those in abundance or those in scarcity, hidden or manifest.", ar: "هكذا أيضاً نذور عبيدك، إقبلها إليك، أصحاب الكثير وأصحاب القليل، الخفيات والظاهرات." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Those who desire to offer to You but have none, and those who have offered these gifts to You this very day,", ar: "والذين يريدون أن يقدموا لك وليس لهم، والذين قدموا لك في هذا اليوم هذه القرابين." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "give them the incorruptible instead of the corruptible, the heavenly instead of the earthly and the eternal instead of the temporal.", ar: "أعطهم الباقيات عوضاً عن الفانيات، السمائيات عوض الأرضيات، الأبديات عوض الزمنيات." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Their houses and their stores, fill them with every good thing.", ar: "بيوتهم ومخازنهم إملأها من كل الخيرات." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Surround them, O Lord, by the power of Your holy angels and archangels. As they remembered Your holy name on earth, remember them also, O Lord, in Your kingdom, and in this age too, leave them not behind.", ar: "أحطهم يا رب بقوة ملائكتك، ورؤساء ملائكتك الأطهار. وكما ذكروا إسمك القدوس على الأرض، أذكرهم هم أيضاً يا رب في ملكوتك، وفي هذا الدهر لا تتركهم عنك." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Lord have mercy.", ar: "يا ربُّ إرحَم." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'heading', text: { en: "Graciously O Lord", ar: "تفضل يا رب" } },
      { kind: 'prayer', text: { en: "Graciously O Lord, keep us this night without sin. Blessed are You, O Lord the God of our fathers and exceedingly blessed, and Your holy name is full of glory forever. Amen.", ar: "تفضَّلْ يا ربُّ أنْ تَحْفَظَنا في هَذِهِ اللَّيْلَةِ بِغَيرِ خَطيَّةٍ. مُبارِكٌ أَنْتَ أيُّها الرَّبُّ إلهُ آبائِنا ومُتَزايدٌ بَرَكةً، وإسْمُكَ القُدُّوسُ مَمْلوءٌ مَجْداً إلَى الأبَدِ. آمين." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Let Your mercies be upon us, O Lord, even as we rely on You. For the eyes of all hope in You, for You give them their food in due season.", ar: "فَلْتكنْ رَحمَتُكَ عَليْنا كَمثْلِ إتِّكالِنا عَليْكَ، لأنَّ أعْيُنَ الكُلَّ تَترَجَّاكَ، لأنَّكَ أنْتَ الذي تُعْطيهم طَعامَهُم في حينِه." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Hear us, O God our Savior, the hope of the regions of the whole earth. And You O Lord, keep us and deliver us, from this generation and forever. Amen.", ar: "إسْمَعنا يا الله مُخلِّصَنا يا رَجاءَ أقْطارِ الأرْضِ كُلِّها. وأنْتَ يا ربُّ تَحْفظُنا وتُنَجِّينا مِنْ هَذا الجيلِ وإلَى الأبَدِ. آمين." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Blessed are You O Lord, teach me Your justice. Blessed are You O Lord, make me to understand Your rights. Blessed are You O Lord, enlighten me in Your righteousness.", ar: "مُبارَكٌ أنْتَ يا ربُّ، عَلِّمني عَدْلَك. مُبارَكٌ أنْتَ يا ربُّ، فَهِّمني حُقوقَكَ. مُبارَكٌ أنْتَ يا ربُّ، أنِرْ لي بِرَّك." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "O Lord, Your mercy is forever. Do not reject the works of Your hands. For You, O Lord, have become my refuge from generation to generation.", ar: "يا ربُّ رَحْمَتُكَ دائِمَةٌ إلَى الأبَدِ. أعْمالُ يَديْكَ يا ربُّ لا تَرفُضْها، لأنَّكَ صِرْتَ لي مَلجأً مِنْ جيلٍ إلَى جيلٍ." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'heading', text: { en: "The Trisagion", ar: "الثلاث تقديسات" } },
      { kind: 'prayer', text: { en: "Holy God, holy Mighty, holy Immortal, who was born of the Virgin, have mercy upon us.", ar: "قُدُّوسٌ الله، قُدُّوسٌ القَويُّ، قُدُّوسٌ الحَيُّ الَّذي لا يَموتُ، الَّذي وُلِدَ مِنَ العَذْراءِ، إرْحَمْنا." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Holy God, holy Mighty, holy Immortal, who was crucified for us, have mercy upon us.", ar: "قُدُّوسٌ الله، قُدُّوسٌ القَويُّ، قُدُّوسٌ الحَيُّ الَّذي لا يَموتُ، الَّذي صُلِبَ عنَّا، إرْحَمْنا." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Holy God, holy Mighty, holy Immortal, who rose from the dead and ascended into the heavens, have mercy upon us.", ar: "قُدُّوسٌ الله، قُدُّوسٌ القَويُّ، قُدُّوسٌ الحَيُّ الَّذي لا يَموتُ، الذي قامَ مِنَ الأمْواتِ وصَعِدَ إلَى السَّمواتِ، إرْحَمْنا." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Glory to the Father and to the Son and the Holy Spirit, now and forever and unto the ages of all ages. Amen.", ar: "المجْدُ للآبِ والإبنِ والرُّوحِ القُدُسِ، الآنَ وكلُّ أَوان وإلَى دَهْرِ الدُّهورِ. آمين." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "O Holy Trinity, have mercy upon us. O Holy Trinity, have mercy upon us. O Holy Trinity, have mercy upon us.", ar: "أيُّها الثَّالوثُ القُدُّوسُ إرْحَمْنا. أيُّها الثَّالوثُ القُدُّوسُ إرْحَمْنا. أيُّها الثَّالوثُ القُدُّوسُ إرْحَمْنا." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Lord, forgive our sins. Lord, forgive our iniquities. Lord, forgive our transgressions. Lord, be with the sick of Your people, heal them for the sake of Your holy name. Our fathers and brethren who have slept, repose their souls.", ar: "يا رَبُّ إغْفِرْ لَنا خَطايانا. يا رَبُّ إغْفِرْ لَنا آثامَنا. يا رَبُّ إغْفِرْ لَنا زَلاَّتَنا. يا رَبُّ إفْتَقدْ مَرْضَى شَعْبكَ، إشْفِهمْ مِنْ أجْل إسْمكَ القُدُّوسِ. آباؤُنا وإخْوَتنا الَّذينَ رَقدوا، يا رَبُّ نَيِّحْ نُفوسَهُم." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "O who are alone is sinless, help us and accept our prayers. For Yours is the glory, dominion, and triple holiness. Lord have mercy. Lord have mercy. Lord bless us. Amen.", ar: "يا مَنْ هُوَ بِلا خَطيَّة، يا ربُّ إرحَمنا. يا مَنْ بِلا خَطيَّةِ، يا رَبُّ أَعِنَّا، وإقْبَلْ طَلباتِنا إلَيْكَ. لأنَّ لَكَ المجْدَ والعِزَّةَ والتَّقْديسَ المثلَّثَ. يا ربُّ إرحَم. يا ربُّ إرحَم. يا رَبُّ بارِكْ. آمين." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'heading', text: { en: "Our Father", ar: "أبانا الذي" } },
      { kind: 'prayer', text: { en: "Our Father who art in heaven, hallowed be Thy name. Thy kingdom come. Thy will be done, on earth as it is in heaven. Give us this day our daily bread; and forgive us our trespasses, as we forgive those who trespass against us; and lead us not into temptation, but deliver us from the evil one. In Christ Jesus our Lord, for Thine is the kingdom and the power and the glory forever. Amen.", ar: "أبانا الذي في السموات، ليتقدس إسمك. ليأت ملكوتك. لتكن مشيئتك، كما في السماء كذلك على الأرض. خبزنا كفافنا أعطنا اليوم. وأغفر لنا ذنوبنا، كما نغفر نحن أيضاً للمذنبين إلينا. ولا تدخلنا في تجربة، لكن نجنا من الشرير. بالمسيح يسوع ربنا، لأن لك الملك والقوة والمجد إلى الأبد. آمين." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'heading', text: { en: "Introduction to the Creed", ar: "بدء قانون الإيمان" } },
      { kind: 'prayer', text: { en: "We exalt you, the Mother of the true Light, and we glorify you, O saint and Theotokos, for you brought forth unto us the Savior of the whole world; He came and saved our souls.", ar: "نُعظِّمُكِ يا أمَّ النُّورِ الحَقيقيِّ، ونُمجِّدكِ أيَّتُها العَذْراءُ القِدِّيسةُ، والِدةُ الإلهِ، لأنَّكِ وَلدْتِ لَنا مُخلِّصَ العالَم، أتَى وخَلَّصَ نُفوسَنا." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Glory to You, our Master, our King, Christ, the pride of the Apostles, the crown of the martyrs, the joy of the righteous, the steadfastness of the churches, and the forgiveness of sins.", ar: "المجْدُ لكَ يا سَيِّدُنا ومَلكُنا المسيحُ، فَخْرَ الرُّسُل، إكْليلَ الشُهداءِ، تَهْليلَ الصِدِّيقينَ، ثَباتَ الكَنائسِ، غُفْرانَ الخَطايا" }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "We proclaim the Holy Trinity in one Godhead. We worship Him. We glorify Him. Lord have mercy. Lord have mercy. Lord bless. Amen.", ar: "نُبشِّرُ بالثَّالوثِ القُدُّوسِ، لاهوتٌ واحِدٌ، نَسجُدُ لهُ ونُمجِّدهُ. يا ربُّ إرحَم. يا ربُّ إرحَم. يا رَبُّ بارِكْ. آمين." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'heading', text: { en: "The Orthodox Creed", ar: "قانون الإيمان الأرثوذكسي" } },
      { kind: 'prayer', text: { en: "We believe in one God, God the Father, the Pantocrator, who created heaven and earth, and all things, seen and unseen.", ar: "بالحقيقة نؤمن بإله واحد، الله الآب، ضابط الكل، خالق السماء والأرض، ما يُرى وما لا يُرى." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "We believe in one Lord Jesus Christ, the only-begotten Son of God, begotten of the Father before all ages.", ar: "نؤمن برب واحد يسوع المسيح، إبن الله الوحيد، المولود من الآب قبل كل الدهور." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Light out of Light, true God of true God; begotten not created, of one essence with the Father, by whom all things were made; who for us men and for our salvation, came down from heaven, and was incarnate of the Holy Spirit and of the Virgin Mary, and became man.", ar: "نور من نور، إله حق من إله حق. مولود غير مخلوق، مساوي للآب في الجوهر، الذي به كان كل شيء. هذا الذي من أجلنا نحن البشر، ومن أجل خلاصنا، نزل من السماء، وتجسد من الروح القدس ومن مريم العذراء، وتأنس." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "And He was crucified for us under Pontius Pilate, suffered and was buried. And on the third day He rose from the dead, according to the Scriptures.", ar: "وصلب عنا على عهد بيلاطس البنطي، وتألم وقبر. وقام من بين الأموات في اليوم الثالث كما في الكتب." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "He ascended into the heavens and sits at the right hand of His Father, and He is coming again in His glory to judge the living and the dead, whose kingdom shall have no end.", ar: "وصعد إلى السموات، وجلس عن يمين أبيه، وأيضاً يأتي في مجده ليدين الأحياء والأموات، الذي ليس لملكه إنقضاء." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Yes, we believe in the Holy Spirit, the Lord, the Life-Giver, who proceeds from the Father, who, with the Father and the Son, is worshippedand glorified, who spoke by the prophets.", ar: "نعم نؤمن بالروح القدس، الرب المحيي المنبثق من الآب. نسجد له ونمجده مع الآب والإبن، الناطق في الأنبياء." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "And in one holy, catholic and apostolic Church. We confess one baptism for the remission of sins.", ar: "وبكنيسة واحدة مقدسة جامعة رسولية. ونعترف بمعمودية واحدة لمغفرة الخطايا." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "We look for the resurrection of the dead, and the life of the age to come. Amen.", ar: "وننتظر قيامة الأموات وحياة الدهر الآتي. آمين." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'heading', text: { en: "O God, Have Mercy Upon Us", ar: "اللهُمَّ إرحمنا" } },
      { kind: 'prayer', text: { en: "O God, have mercy upon us, settle mercy upon us, have compassion upon us.", ar: "اللهُمَّ إرحمنا، قرر لنا رحمة، تراءف علينا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Amen.", ar: "آمين." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Hear us.", ar: "وإسمعنا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Amen.", ar: "آمين." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Bless us, keep us, and help us.", ar: "وباركنا وإحفظنا وأعنا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Amen.", ar: "آمين." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Take away Your anger from us, visit us with Your salvation, and forgive us our sins.", ar: "وإرفع غضبك عنا، وإفتقدنا بخلاصك، وإغفر لنا خطايانا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Amen.", ar: "آمين." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Lord have mercy (3).", ar: "يا ربُّ إرحَم (3)." } },
      { kind: 'heading', text: { en: "Litany for the Gospel", ar: "أوشية الإنجيل" } },
      { kind: 'litany', text: { en: "Pray.", ar: "صلوا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Stand up for prayer.", ar: "للصلاة قفوا." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'litany', text: { en: "Peace be with all.", ar: "السلام لجميعكم." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "And with your spirit.", ar: "ولروحك أيضاً." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'litany', text: { en: "O Master, Lord Jesus Christ our God, who said to His saintly, honored Disciples and holy Apostles,", ar: "أيها السيد الرب يسوع المسيح إلهنا، الذي قال لتلاميذه القديسين ورسله الأطهار المكرمين:" }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "“Many prophets and righteous men have desired to see the things which you see, and have not seen them, and to hear the things which you hear and have not heard them. But as for you, blessed are your eyes, for they see, and your ears for they hear.”", ar: "\"إن أنبياء وأبراراً كثيرين إشتهوا أن يروا ما أنتم ترون ولم يروا، وأن يسمعوا ما أنتم تسمعون ولم يسمعوا. أما أنتم فطوبى لأعينكم لأنها تبصر، ولآذانكم لأنها تسمع.\"" } },
      { kind: 'litany', text: { en: "May we be worthy to hear and to act according to Your Holy Gospels, through the prayers of Your saints.", ar: "فلنستحق أن نسمع ونعمل بأناجيلك المقدسة بطلبات قديسيك." } },
      { kind: 'litany', text: { en: "Pray for the Holy Gospel.", ar: "صلوا من أجل الإنجيل المقدس." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'litany', text: { en: "Lord have mercy.", ar: "يا ربُّ إرحَم." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'litany', text: { en: "Remember also, O our Master, all those who have bidden us to remember them in our supplications and prayers which we offer up unto You, O Lord our God. Those who already fallen asleep, repose them.", ar: "أُذكر أيضاً يا سيدنا كل الذين أوصونا أن نذكرهم في تضرعاتنا وطلباتنا التي نصعدها إليك أيها الرب إلهنا. الذين سبقوا فرقدوا، نيحهم. المرضى إشفهم." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Those who are sick, heal them. For You are the life of us all, the salvation of us all, the hope of us all, the healing of us all, and the resurrection of us all.", ar: "لأنك أنت حياتنا كلنا، وخلاصنا كلنا، ورجاؤنا كلنا، وشفاؤنا كلنا، وقيامتنا كلنا." } },
      { kind: 'heading', text: { en: "Another Litany for the Gospel", ar: "أوشية إنجيل أخرى" } },
      { kind: 'litany', text: { en: "O Master, Lord Jesus Christ our God, who sent His saintly, honored Disciples and holy Apostles into all the world", ar: "أيها السيد الرب يسوع المسيح إلهنا الذي أرسل تلاميذه القديسين المكرمين، ورسله الأطهار في العالم كله." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "that they may preach the Gospel of Your kingdom and teach all nations Your true knowledge.", ar: "ليكرزوا بإنجيل ملكوتك ويعلموا كل الأمم معرفتك الحقيقية." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "We ask You, O our Master, open the ears of our hearts that we may hear Your Holy Gospel—", ar: "نسألك يا سيدنا، إفتح أذان قلوبنا لكي نسمع أناجيلك المقدسة." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Pray for the Holy Gospel.", ar: "صلوا من أجل الإنجيل المقدس." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'litany', text: { en: "Lord have mercy.", ar: "يا ربُّ إرحَم." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'litany', text: { en: "And open the senses of our souls, and may we be worthy not only to be hearers but to act according to Your holy commandments though the good will of God, Your good Father.", ar: "وإفتح حواس نفوسنا، ولنستحق أن نكون ليس فقط سامعين، بل عاملين أيضاً بأوامرك المقدسة، كمسرة الله أبيك الصالح." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'heading', text: { en: "Psalm of the Gospel", ar: "المزمور" } },
      { kind: 'rubric', text: { en: "A psalm of David, chanted before the Holy Gospel", ar: "A psalm of David, chanted before the Holy Gospel" } },
      { kind: 'rubric', text: { en: "The Psalm of the day, chanted before the Gospel.", ar: "مزمور اليوم، يُرتل قبل الإنجيل." } },
      { kind: 'heading', text: { en: "The Holy Gospel", ar: "الإنجيل" } },
      { kind: 'rubric', text: { en: "The Holy Gospel — the reading appointed for this day.", ar: "الإنجيل المقدس — القراءة المعينة لهذا اليوم." } },
      { kind: 'heading', text: { en: "Gospel Response", ar: "مرد الإنجيل" } },
      { kind: 'prayer', text: { en: "Zacchaeus said to his Lord, “The half of my goods, I will give O Master, to the poor with care.”", ar: "فقال زكا لربه، \"نصف أموالي، أعطيها يا سيدي، للمساكين بحرص.\"" }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "The Lord God of powers said, “Behold salvation has come unto you today, for you are also, a son of Abraham.”", ar: "أجاب الرب إله القوات، \"هوذا الخلاص قد وجب لك اليوم، لأنك أنت أيضاً، إبن إبراهيم.\"" }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "For blessed be ....", ar: "لأنه مبارك ..." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'heading', text: { en: "Litany for the Peace", ar: "أوشية السلام" } },
      { kind: 'litany', text: { en: "Again, let us ask God the Pantocrator, the Father of our Lord, God, and Savior Jesus Christ.", ar: "وأيضاً فلنسأل الله الضابط الكل، أبا ربنا وإلهنا ومخلصنا يسوع المسيح." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "We ask and entreat Your goodness, O Lover of Mankind, remember, O Lord, the peace of Your one, only, holy, catholic, and apostolic Church—", ar: "نسأل ونطلب من صلاحك يا محب البشر، أُذكر يا رب سلام كنيستك الواحدة الوحيدة المقدسة الجامعة الرسولية." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Pray for the peace of the one, holy, catholic, and apostolic orthodox Church of God.", ar: "صلوا من أجل سلام الواحدة المقدسة الجامعة الرسولية كنيسة الله الأرثوذكسية." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'litany', text: { en: "Lord have mercy.", ar: "يا ربُّ إرحَم." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'litany', text: { en: "that which exists from one end of the world to the other.", ar: "هذه الكائنة من أقاصي المسكونة إلى أقاصيها." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'heading', text: { en: "Litany for the Fathers", ar: "أوشية الآباء" } },
      { kind: 'litany', text: { en: "Remember, O Lord, our patriarch, the honored father and high priest, Pope Abba (Tawadros II).", ar: "أُذكر يا رب بطريركنا الأب المكرم رئيس الكهنة البابا المعظم أنبا (تواضروس الثاني)،" }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "and his spiritual brothers, the Patriarch of Antioch Mar Ignatius (…), and the Patriarch of Eritrea Abouna (…).", ar: "وأخوية الروحيين مار إغناطيوس (...) بطريرك أنطاكية وأبونا (...) بطريرك إريتريا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'rubric', text: { en: "In the presence of a bishop:", ar: "في حضور الأب الأسقف:" } },
      { kind: 'litany', text: { en: "and his partner in the liturgy, our father the bishop (metropolitan), Abba (…).", ar: "وشريكة في الخدمة الرسولية أبينا الأسقف (المطران) الأنبا (...)." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Pray for our high priest, Pope Abba (Tawadros II), pope and patriarch and archbishop of the great city of Alexandria,", ar: "صلوا من أجل رئيس كهنتنا البابا أنبا (تواضروس الثاني)، بابا وبطريرك ورئيس أساقفة المدينة العظمى الاسكندرية،" }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'litany', text: { en: "and his spiritual brothers, the Patriarch of Antioch Mar Ignatius (…), and the Patriarch of Eritrea Abouna (…).", ar: "وأخوية الروحيين مار إغناطيوس (...) بطريرك أنطاكية وأبونا (...) بطريرك إريتريا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'rubric', text: { en: "In the presence of a bishop:", ar: "في حضور الأب الأسقف:" } },
      { kind: 'litany', text: { en: "and his partner in the liturgy, our father the bishop (metropolitan), Abba (…),", ar: "وشريكة في الخدمة الرسولية أبينا الأسقف (المطران) الأنبا (...)،" }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'rubric', text: { en: "And concludes with:", ar: "وينهي:" } },
      { kind: 'litany', text: { en: "and for our orthodox bishops.", ar: "وسائر أساقفتنا الأرثوذكسيين." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Lord have mercy.", ar: "يا ربُّ إرحَم." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'litany', text: { en: "In keeping, keep them for us for many years and peaceful times.", ar: "حفظاً إحفظهم لنا سنين كثيرة وأزمنة سلامية." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'heading', text: { en: "Litany for the Place", ar: "أوشية الموضع" } },
      { kind: 'litany', text: { en: "Remember, O Lord, the salvation of this, Your holy place, and every place, and every monastery of our orthodox fathers—", ar: "أُذكر يا رب خلاص هذا الموضع المقدس الذي لك، وكل المواضع وكل أديرة آبائنا الأرثوذكسيين." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Pray for the salvation of the world and of this city of ours, and of all cities, districts, island, and monasteries.", ar: "صلوا من أجل خلاص هذا العالم ومدينتنا هذة، وسائر المدن والأقاليم والجزائر والأديرة." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'litany', text: { en: "Lord have mercy.", ar: "يا ربُّ إرحَم." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'litany', text: { en: "and every city and every region, and the villages and all their adornments.", ar: "وكل مدينة، وكل كورة، والقرى وكل زينتها." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "And save us all from famine, plagues, earthquakes, drowning, fire, captivity by barbarians, the sword of the stranger, and the rising up of heretics.", ar: "ونجنا كلنا من الغلاء، والوباء، والزلزال، والغرق، والحريق، وسبي البربر، ومن سيف الغريب، ومن قيام الهراطقة." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Lord have mercy.", ar: "يا ربُّ إرحَم." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'heading', text: { en: "Litany for the Nature", ar: "أوشية الطبيعة" } },
      { kind: 'rubric', text: { en: "Season of the waters", ar: "موسم المياه" } },
      { kind: 'heading', text: { en: "Litany of the Waters", ar: "أوشية المياه" } },
      { kind: 'litany', text: { en: "Graciously accord, O Lord, to bless the waters of the river this year.", ar: "تفضل يا رب مياه النهر في هذه السنة، باركها." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Pray for the rising of the waters of the rivers this year, that Christ our God may bless them and raise them according to their measure, that He may give joy to the face of the earth, sustain us, the sons of men, save the cattle, and forgive us our sins.", ar: "أُطلبوا عن صعود مياه الأنهار في هذا السنة، لكيْ يباركها المسيح إلهنا، ويصعدها كمقدارها، ويفرِّح وجه الأرض، ويعولنا نحن بني البشر، ويعطي النجاة للبهائم، ويغفر لنا خطايانا." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'litany', text: { en: "Lord have mercy (3).", ar: "يا ربُّ إرحَم (3)." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'rubric', text: { en: "Season of the plants", ar: "موسم الزروع" } },
      { kind: 'heading', text: { en: "Litany of the Plants", ar: "أوشية الزروع" } },
      { kind: 'litany', text: { en: "Graciously accord, O Lord, to bless the seeds, the herbs, and the plants of the field this year.", ar: "تفضل يا رب، الزروع والعشب ونبات الحقل في هذه السنة، باركها." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Pray for the seeds, the herbs, and the plants of the field this year, that Christ our God may bless them to grow and multiply unto perfection with great fruit, have compassion on His creation which His hands have made, and forgive us our sins.", ar: "أُطلبوا عن الزروع والعشب ونبات الحقل، في هذه السنة، لكيْ يباركها المسيح إلهنا، لتنمو وتكثر إلى أن تكمل بثمرة عظيمة، ويتحنن على جبلته التي صنعتها يداه، ويغفر لنا خطايانا." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'litany', text: { en: "Lord have mercy (3).", ar: "يا ربُّ إرحَم (3)." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'rubric', text: { en: "Season of the fruits", ar: "موسم الثمار" } },
      { kind: 'heading', text: { en: "Litany of the Fruits", ar: "أوشية الثمار" } },
      { kind: 'litany', text: { en: "Graciously accord, O Lord, to bless the air of heaven and the fruits of the earth this year.", ar: "تفضل يا رب أهوية السماء وثمرات الأرض، في هذه السنة، باركها." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Pray for the air of heaven, the fruits of the earth, the trees, the vines, and for every fruit-bearing tree in all the world, that Christ our God may bless them, bring them to perfection in peace without harm, and forgive us our sins.", ar: "أُطلبوا عن أهوية السماء، وثمرات الأرض والشجر والكروم، وكل شجرة مثمرة في كل المسكونة، لكي يباركها المسيح إلهنا، ويكملها سالمة بغير ألم، ويغفر لنا خطايانا." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'litany', text: { en: "Lord have mercy (3).", ar: "يا ربُّ إرحَم (3)." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'litany', text: { en: "Raise them to their measure according to Your grace. Give joy to the face of the earth. May its furrows be abundantly watered and its fruits be plentiful.", ar: "اصعِدْها كمقدارِها كنعمَتِكَ، فَرِّحْ وجهَ الأرضِ، ليُرْوَ حرثُها ولتكثرَ أثمارُها." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Prepare it for sowing and harvesting. Manage our lives as deemed fit.", ar: "أعِدَّها للزرعِ والحصادِ، ودَبِّر حياتَنا كما يليق." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Bless the crown of the year with Your goodness for the sake of the poor of Your people, the widow, the orphan, the traveler, the stranger, and for the sake of all of us who entreat You and seek Your holy name.", ar: "بَارِكْ إكليلَ السنةِ بصلاحِكَ، من أجلِ فقراءِ شعبِكَ، من أجلِ الأرملةِ واليتيمِ والغريبِ والضيفِ، ومن أجلِنا كُلِّنا نحنُ الذين نرجوكَ ونطلبُ إسمَكَ القدوس." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "For the eyes of everyone wait upon You, for You give them their food in due season.", ar: "لأن أعينَ الكلِّ تترجاكَ، لأنَّكَ أنتَ الذي تُعطِيهم طعامَهم في حينٍ حسنٍ." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Deal with us according to Your goodness, O You who give food to all flesh. Fill our hearts with joy and gladness, that we too, having sufficiency in everything always, may abound in every good deed.", ar: "إصنع معنا حَسَبَ صلاحِكَ، يا مُعطِياً طعاماً لكلِّ جسدٍ. املأ قلوبَنا فرحاً ونعيماً، لكي نحنُ أيضاً إذ تكونَ لنا الكفايةُ في كلِّ شيءٍ، كلَّ حينٍ، نزدادَ في كلِّ عملٍ صالحٍ." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'heading', text: { en: "Litany for the Assemblies", ar: "أوشية الإجتماعات" } },
      { kind: 'litany', text: { en: "Again, let us ask God the Pantocrator, the Father of our Lord, God, and Savior Jesus Christ.", ar: "وأيضاً فلنسأل الله الضابط الكل، أبا ربنا وإلهنا ومخلصنا يسوع المسيح." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "We ask and entreat Your goodness, O Lover of Mankind, remember, O Lord, our assemblies.", ar: "نسأل ونطلب من صلاحك يا محب البشر، أُذكر يا رب إجتماعاتنا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Bless them.", ar: "باركها." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Pray for this holy church and for our assemblies.", ar: "صلوا من أجل هذه الكنيسة المقدسة وإجتماعاتنا." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'litany', text: { en: "Lord have mercy.", ar: "يا ربُّ إرحَم." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'litany', text: { en: "Grant that they may be to us without obstacle or hindrance, that we may hold them according to Your holy and blessed will:", ar: "أعط أن تكون لنا بغير مانع ولا عائق، لنصنعها كمشيئتك المقدسة الطوباوية." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "houses of prayer, houses of purity, houses of blessing. Grant them to us, O Lord, and Your servants who shall come after us, forever.", ar: "بيوت صلاة، بيوت طهارة، بيوت بركة، أنعم بها لنا يا رب، ولعبيدك الآتين بعدنا إلى الأبد." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'rubric', text: { en: "The following may be said:", ar: "يمكن يقال الآتي:" } },
      { kind: 'litany', text: { en: "The worship of idols, utterly uproot from the world.", ar: "عبادة الأوثان بتمامها، إقلعها من العالم." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Satan and all his evil powers, trample and humiliate under our feet speedily.", ar: "الشيطان وكل قواته الشريرة، إسحقهم وأذلهم تحت أقدامنا سريعاً." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "All offenses and their instigators, do abolish. May all dissensions of corrupt heresies cease.", ar: "الشكوك وفاعليها إبطلهم. ولينقض إفتراقات فساد البدع." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "The enemies of Your holy Church, O Lord, as at all times, now also humiliate.", ar: "أعداء كنيستك المقدسة يا رب، مثل كل زمان، الآن أيضاً أذلهم." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Strip their vanity, show them their weakness speedily.", ar: "حل تعاظمهم، عرفهم ضعفهم سريعاً." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Bring to naught their envy, their intrigues, their madness, their wickedness, and their slander, which they commit against us.", ar: "أبطل حسدهم، وسعايتهم، وجنونهم، وشرهم، ونميمتهم التي يصنعونها فينا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "O Lord, bring them all to no avail. Disperse their counsel, O God, who dispersed the counsel of Ahithophel.", ar: "يا رب إجعلهم كلهم كلا شئ، وبدد مشورتهم يا الله الذي بدد مشورة أخيتوفل." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Amen.", ar: "آمين." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'litany', text: { en: "Lord have mercy.", ar: "يا ربُّ إرحَم." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'rubric', text: { en: "Then the following is said:", ar: "ثم يكمل بالآتي:" } },
      { kind: 'litany', text: { en: "Arise, O Lord God, let all Your enemies be scattered, and let all who hate Your holy name flee before Your face.", ar: "قم أيها الرب الإله. وليتفرق جميع أعدائك. وليهرب من قدام وجهك كل مبغضي إسمك القدوس." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "But let Your people be in blessing, thousands of thousands and ten thousand times ten thousand doing Your will,", ar: "وأما شعبك فليكن بالبركة، ألوف ألوف وربوات ربوات، يصنعون إرادَتك." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "by the grace, compassion and love-of-mankind, of Your only-begotten Son, our Lord, God, and Savior, Jesus Christ.", ar: "بالنعمة والرأفات ومحبة البشر اللواتي لإبنك الوحيد ربنا وإلهنا ومخلصنا يسوع المسيح." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Through whom the glory, the honor, the dominion, and the worship are due unto You, with Him and the Holy Spirit, the Giver of Life, who is of one essence with You, now and at all times, and unto the age of all ages. Amen.", ar: "هذا الذي من قبله المجد والإكرام والعزة والسجود تليق بك معه، مع الروح القدس المحيي المساوي لك. الآن وكل أوان وإلى دهر الدهور. آمين." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Make us worthy to pray thankfully:", ar: "وإجعلنا مستحقين أن نقول بشكر:" }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "“Our Father who art in heaven…”", ar: "\"أبانا الذي في السموات...\"" }, label: { en: "People", ar: "الشعب" } },
      { kind: 'litany', text: { en: "In Christ Jesus our Lord.", ar: "بالمسيح يسوع ربنا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'heading', text: { en: "Our Father", ar: "أبانا الذي" } },
      { kind: 'prayer', text: { en: "Our Father who art in heaven, hallowed be Thy name. Thy kingdom come. Thy will be done, on earth as it is in heaven. Give us this day our daily bread; and forgive us our trespasses, as we forgive those who trespass against us; and lead us not into temptation, but deliver us from the evil one. In Christ Jesus our Lord, for Thine is the kingdom and the power and the glory forever. Amen.", ar: "أبانا الذي في السموات، ليتقدس إسمك. ليأت ملكوتك. لتكن مشيئتك، كما في السماء كذلك على الأرض. خبزنا كفافنا أعطنا اليوم. وأغفر لنا ذنوبنا، كما نغفر نحن أيضاً للمذنبين إلينا. ولا تدخلنا في تجربة، لكن نجنا من الشرير. بالمسيح يسوع ربنا، لأن لك الملك والقوة والمجد إلى الأبد. آمين." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'heading', text: { en: "The Conclusion", ar: "الختام" } },
      { kind: 'prayer', text: { en: "Amen.", ar: "آمين." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Lord have mercy (3).", ar: "يا ربُّ إرحَم (3)." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Amen, alleluia. Glory to the Father and the Son and the Holy Spirit, now and ever and unto the age of all ages, amen.", ar: "آمين، هلليلويا. المجد للآب والإبن والروح القدس، الآن وكل أوان وإلى دهر الدهور، آمين." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "We proclaim saying: “O our Lord Jesus Christ.", ar: "نصرخ قائلين: \"يا ربنا يسوع المسيح." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Bless the air of heaven, the waters of the river, and the seeds and the herbs.", ar: "بارك أهوية السماء، مياه النهر والزروع والعشب." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "May Your mercy and Your peace be a fortress to Your people.", ar: "ولتكن رحمتك وسلامك حصناً لشعبك." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Save us and have mercy upon us.”", ar: "خلصنا وإرحمنا.\"" }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Lord have mercy, Lord have mercy, Lord bless amen. Bless me, bless me, behold the repentance, forgive me, say the blessing.", ar: "يا ربُّ إرحَم، يا ربُّ إرحَم، يا رب بارك آمين. باركوا عليَّ، باركوا عليَّ، ها مطانية، إغفروا لي، قُل البركة." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'heading', text: { en: "The Short Blessing", ar: "البركة القصيرة" } },
      { kind: 'prayer', text: { en: "May God have compassion upon us, bless us, manifest His face upon us, and have mercy upon us.", ar: "الله يترأف علينا ويباركنا، ويظهر وجهه علينا ويرحمنا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "O Lord, save Your people, bless Your inheritance, shepherd them, and raise them up forever.", ar: "يا رب خلص شعبك. بارك ميراثك. إرعهم وإرفعهم إلى الأبد." } },
      { kind: 'prayer', text: { en: "Exalt the horn of Christians through the power of the life-giving Cross", ar: "إرفع شأن المسيحيين بقوة الصليب المحيي." } },
      { kind: 'prayer', text: { en: "and through the supplications and prayers which our Lady, the Lady of us all, the holy Theotokos, Saint Mary, makes for us.", ar: "بالسؤالات والطلبات التي تصنعها عنا كل حين سيدتنا وملكتنا كلنا والدة الإله القديسة الطاهرة مريم." } },
      { kind: 'prayer', text: { en: "And [through the supplications and prayers of] the three great holy luminaries Michael, Gabriel, and Raphael;", ar: "والثلاثة العظماء المنيرون الأطهار ميخائيل وغبريال وروفائيل." } },
      { kind: 'prayer', text: { en: "the four incorporeal creatures; the twenty-four priests; all the heavenly orders;", ar: "والأربعة الحيوانات غير المتجسدين، والأربعة والعشرون قسيساً وكل الطغمات السمائية." } },
      { kind: 'prayer', text: { en: "Saint John the Baptist; the hundred and forty-four thousand; my masters and fathers the apostles; the three holy youths; Saint Stephen;", ar: "والقديس يوحنا المعمدان، والمائة والأربعة والأربعين ألفاً، وسادتي الآباء الرسل، والثلاثة فتية القديسين، والقديس إستفانوس." } },
      { kind: 'prayer', text: { en: "the beholder-of-God, Saint Mark the Evangelist, the apostle and martyr;", ar: "وناظر الإله الإنجيلي مرقس الرسول القديس والشهيد." } },
      { kind: 'prayer', text: { en: "Saint George; Saint Theodore; Philopater Mercurius; Saint Abba Mina; and the whole choir of the martyrs;", ar: "والقديس جرجس، والقديس تادرس، وفيلوباتير مرقوريوس، والقديس أبا مينا، وكل مصاف الشهداء." } },
      { kind: 'prayer', text: { en: "our righteous father, the great Abba Anthony; the righteous Abba Paul; the three saints Abba Macarii;", ar: "وأبونا الصديق العظيم الأنبا أنطونيوس، والبار أنبا بولا، والثلاثة أنبا مقارات القديسون." } },
      { kind: 'prayer', text: { en: "our father Abba John; our father Abba Pishoi; our father Abba Paul of Tammoh; our Roman fathers Maximus and Dometius; our father Abba Moses; the Forty-nine Martyrs;", ar: "وأبونا أنبا يوحنا، وأبونا أنبا بيشوي، وأبونا أنبا بولا الطموهي، وأبوانا الروميان مكسيموس ودوماديوس، وأبونا انبا موسى، والتسعة والأربعون شهيداً." } },
      { kind: 'prayer', text: { en: "the whole choir of the cross-bearers; the just; the righteous; all the wise virgins; the angel of this blessed night.", ar: "وكل مصاف لباس الصليب والأبرار والصديقون، وجميع العذارى الحكيمات، وملاك هذه الليلة المباركة." } },
      { kind: 'rubric', text: { en: "(The patron saint of the church is mentioned, followed by the saint(s) of the day.)", ar: "ههنا يذكر اسم صاحب الكنيسة ثم يقول:" } },
      { kind: 'prayer', text: { en: "and the blessing of the holy Theotokos, first and last.", ar: "وبركة والدة الإله القديسة الطاهرة مريم أولاً وآخراً." } },
      { kind: 'rubric', text: { en: "On Sundays", ar: "في أيام الآحاد" } },
      { kind: 'prayer', text: { en: "and the blessing of the Lord’s Day of our good Savior.", ar: "وبركة يوم الأحد الذي لمخلصنا الصالح." } },
      { kind: 'prayer', text: { en: "May their holy blessing, their grace, their power, their gift, their love, and their help rest upon us all forever. Amen.", ar: "بركتهم المقدسة، ونعمتهم، وقوتهم، وهبتهم، ومحبتهم، ومعونتهم تكون معنا كلنا إلى الآبد. آمين." } },
      { kind: 'rubric', text: { en: "The priest casts water on the congregation, saying,", ar: "ويرش الكاهن الشعب ويقول:" } },
      { kind: 'prayer', text: { en: "O Christ our God—", ar: "أيها المسيح إلهنا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Amen. So be it.", ar: "آمين يكون." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "O King of peace, grant us Your peace, establish for us Your peace, and forgive us our sins. For Yours is the power, the glory, the blessing, and the might, forever. Amen.", ar: "يا ملك السلام، أعطينا سلامك. قرر لنا سلامك وإغفر لنا خطايانا. لأن لك القوة والمجد والبركة والعزة إلى الأبد. آمين." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Make us worthy to pray thankfully:", ar: "وإجعلنا مستحقين أن نقول بشكر:" } },
      { kind: 'prayer', text: { en: "“Our Father who art in heaven…”", ar: "\"أبانا الذي في السموات...\"" }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "The grace of our Lord, God, and Savior Jesus Christ be with you all.", ar: "ونعمة ربنا وإلهنا ومخلصنا يسوع المسيح مع جميعكم." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Go in peace. The Lord be with you all.", ar: "إمضوا بسلام. الرب مع جميعكم." } },
      { kind: 'rubric', text: { en: "Or he says:", ar: "أو يقول:" } },
      { kind: 'prayer', text: { en: "The love of God the Father; the grace of the only-begotten Son, our Lord, God, and Savior Jesus Christ; and the communion and gift of the Holy Spirit be with you all. Go in peace. The peace of the Lord be with you all.", ar: "محبة الله الآب، ونعمة الإبن الوحيد، ربنا وإلهنا وملكنا ومخلصنا يسوع المسيح، وشركة وموهبة الروح القدس تكون مع جميعكم. إمضوا بسلام، سلام الرب مع جميعكم." } },
      { kind: 'prayer', text: { en: "And with your spirit.", ar: "مع روحك أيضاً." }, label: { en: "People", ar: "الشعب" } }
    ],
  }
];
